  lines = {
    { id = "area:1086:text", html = false,
      ja = "Toxic Foggerを設置する",
      out = "トキシック・フォガーを設置する" },
    { id = "area:76:text", html = false,
      ja = "Jasperlode Mineの中を偵察する",
      out = "ジャスパーロード・マインの中を偵察する" },
    { id = "book:1031:text", html = true,
      ja = "<HTML>\n<BODY>\n<BR/>\n<BR/>\n<P>\n我が敬愛する師、Horatio M. Montgomery, M.D.を偲んで。治療師、Teacher、友。\n</P>\n<BR/>\n<H1 align=\"center\">\n50 BTFT - 25 ATFT\n</H1>\n<BR/>\n<P>\n「世界は病める者と疲れ果てた者で満ちている。治療師として、いや、医学に携わる男として女として、その『itis』を彼らすべてから一掃することこそ、我々の務めなのだ。」 \n</P>\n<BR/>\n<P>\n- H.M.M., M.D., PhD, JD, Grandmaster Farmer, Dancer Extraordinaire, Animalsの友\n</P>\n<BR/>\n</BODY>\n</HTML>",
      out = "<HTML>\n<BODY>\n<BR/>\n<BR/>\n<P>\n我が敬愛する師、ホレイショ・エム・モンゴメリー, エム・ディー.を偲んで。治療師、ティーチャー、友。\n</P>\n<BR/>\n<H1 align=\"center\">\n50 ビーティーエフティー - 25 エーティーエフティー\n</H1>\n<BR/>\n<P>\n「世界は病める者と疲れ果てた者で満ちている。治療師として、いや、医学に携わる男として女として、その『イティス』を彼らすべてから一掃することこそ、我々の務めなのだ。」 \n</P>\n<BR/>\n<P>\n- エイチ・エム・エム., エム・ディー., ピーエイチディー, ジェイディー, グランドマスター・ファーマー, ダンサー・エクストラオーディネール, アニマルの友\n</P>\n<BR/>\n</BODY>\n</HTML>" },
    { id = "book:1514:text", html = true,
      ja = "<HTML>\n<BODY>\n<H1 align=\"center\">\n第2章：Eastern Pylon\n</H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_mini_east\" align=\"left\"/>\n<P align=\"right\">Eastern<BR/>\nPylonは<BR/>\n青、黄、<BR/>\n緑の<BR/>\nクリスタルを受け入れる。</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align=\"left\">Pylonは、青いクリスタルを主な動力源として生み出されるエネルギーに集中する。</P>\n</BODY>\n</HTML>",
      out = "<HTML>\n<BODY>\n<H1 align=\"center\">\n第2章：イースタン・パイロン\n</H1>\n<BR/>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_mini_east\" align=\"left\"/>\n<P align=\"right\">イースタン<BR/>\nパイロンは<BR/>\n青、黄、<BR/>\n緑の<BR/>\nクリスタルを受け入れる。</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align=\"left\">パイロンは、青いクリスタルを主な動力源として生み出されるエネルギーに集中する。</P>\n</BODY>\n</HTML>" },
    { id = "book:1533:text", html = true,
      ja = "<HTML>\n<BODY>\n<H1 align=\"center\">\nWESTERN PYLON 配置図\n</H1>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_west\"/>\n</BODY>\n</HTML>",
      out = "<HTML>\n<BODY>\n<H1 align=\"center\">\nウェスタン・パイロン 配置図\n</H1>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_west\"/>\n</BODY>\n</HTML>" },
    { id = "book:15:text", html = false,
      ja = "Morganへ\n\nGoldshireの商売は繁盛していて、あまりの忙しさに、そちらへ荷を送る暇もありませんでした！\n\nこの手紙を届けた方に、大きな蝋燭をひと包み、そちらへ運んでもらうよう依頼しました（ほら、Koboldsが好んで頭にのせている、あの蝋燭です）。\n\nどうかこの方に私たちからの感謝を伝え、正当な報酬を払ってあげてください。",
      out = "モーガンへ\n\nゴールドシャイアの商売は繁盛していて、あまりの忙しさに、そちらへ荷を送る暇もありませんでした！\n\nこの手紙を届けた方に、大きな蝋燭をひと包み、そちらへ運んでもらうよう依頼しました（ほら、コボルドが好んで頭にのせている、あの蝋燭です）。\n\nどうかこの方に私たちからの感謝を伝え、正当な報酬を払ってあげてください。" },
    { id = "book:1875:text", html = false,
      ja = "トロールの軍勢が崩れて逃げようとすると、Thoradinの軍勢はそれを追い詰め、兵士を最後の一人まで殺戮した。トロールがこの敗北から完全に立ち直ることは決してなく、歴史上トロールが再び一つの国として立ち上がることもなかった。Quel'Thalasが滅亡から救われたことを確信したエルフたちは、Arathorの国とその王Thoradinの血統に忠誠と友情を誓った。人間とエルフは、この先長きにわたって平和な関係を育むこととなる。",
      out = "トロールの軍勢が崩れて逃げようとすると、ソラディンの軍勢はそれを追い詰め、兵士を最後の一人まで殺戮した。トロールがこの敗北から完全に立ち直ることは決してなく、歴史上トロールが再び一つの国として立ち上がることもなかった。ケルサラスが滅亡から救われたことを確信したエルフたちは、アラソールの国とその王ソラディンの血統に忠誠と友情を誓った。人間とエルフは、この先長きにわたって平和な関係を育むこととなる。" },
    { id = "book:2009:text", html = false,
      ja = "Kil'jaedenは、Ner'zhulが人間という種族を世界から一掃する暗黒の使命を果たしたならば、呪いから解放し、宿るための新たな健やかな肉体を与えると約束した。",
      out = "キルジェイデンは、ネルズールが人間という種族を世界から一掃する暗黒の使命を果たしたならば、呪いから解放し、宿るための新たな健やかな肉体を与えると約束した。" },
    { id = "book:220:text", html = false,
      ja = "Stormwindの再建を完了いたしましたが、その時点でStonemasons' Guildへの請求や料金、給金は未払いのまま、何の説明もなく放置されました。当時、Edwin VanCleefがStonemasonsのギルドマスターに選ばれており、彼は我々の仕事への補償を求めて声を上げました。これに対し、Stormwind House of NoblesはStonemasons' Guildの解散を命じ、当然ながらVanCleefは激怒しました。VanCleefは暴動を率い、Stonemasonsを連れて都を去りました。話を続ける前に、この時期に起きた他の出来事で",
      out = "ストームウィンドの再建を完了いたしましたが、その時点でストーンメイソン・ギルドへの請求や料金、給金は未払いのまま、何の説明もなく放置されました。当時、エドウィン・ヴァンクリーフがストーンメイソンのギルドマスターに選ばれており、彼は我々の仕事への補償を求めて声を上げました。これに対し、ストームウィンド・ハウス・オブ・ノーブルはストーンメイソン・ギルドの解散を命じ、当然ながらヴァンクリーフは激怒しました。ヴァンクリーフは暴動を率い、ストーンメイソンを連れて都を去りました。話を続ける前に、この時期に起きた他の出来事で" },
    { id = "book:259:text", html = false,
      ja = "そしてこれが成った暁には、我らの計画の次の段階を始められます。我ら自身の国と、この地域における権力の基盤を得れば、Third Hostを迎える道を整えることができるのです。\n\nまもなく、Legion Lordsは再び空から炎を降らせることで、我らの働きに報いてくださるでしょう！",
      out = "そしてこれが成った暁には、我らの計画の次の段階を始められます。我ら自身の国と、この地域における権力の基盤を得れば、サード・ホストを迎える道を整えることができるのです。\n\nまもなく、レギオン・ロードは再び空から炎を降らせることで、我らの働きに報いてくださるでしょう！" },
    { id = "book:2660:text", html = true,
      ja = "<HTML> <BODY> <H1 align=\"center\">Hordeの下士官・兵の階級</H1><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank01\"/><BR/> <P align=\"right\">First Sergeant</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank04\"/><BR/> <P align=\"right\">Senior Sergeant</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank03\"/><BR/> <P align=\"right\">Sergeant</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank02\"/><BR/> <P align=\"right\">兵卒</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank01\"/><BR/> <P align=\"right\">斥候</P><BR/><BR/> </BODY> </HTML>",
      out = "<HTML> <BODY> <H1 align=\"center\">ホードの下士官・兵の階級</H1><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank01\"/><BR/> <P align=\"right\">ファースト・サージェント</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank04\"/><BR/> <P align=\"right\">シニア・サージェント</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank03\"/><BR/> <P align=\"right\">サージェント</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank02\"/><BR/> <P align=\"right\">兵卒</P><BR/><BR/> <IMG src=\"Interface\\PvPRankBadges\\PvPRank01\"/><BR/> <P align=\"right\">斥候</P><BR/><BR/> </BODY> </HTML>" },
    { id = "book:2676:text", html = true,
      ja = "<HTML>\n<BODY>\n<H1 align=\"center\">ALLIANCEの軍階級</H1><BR/>\n<P align=\"center\">士官</P><BR/>\n<P align=\"center\">Grand Marshal</P>\n<P align=\"center\">Field Marshal</P>\n<P align=\"center\">Marshal</P>\n<P align=\"center\">Commander</P>\n<P align=\"center\">Lieutenant Commander</P>\n<P align=\"center\">Knight-Champion</P>\n<P align=\"center\">Knight-Captain</P>\n<P align=\"center\">Knight-Lieutenant</P>\n<P align=\"center\">Knight</P><BR/>\n<P align=\"center\">下士官・兵</P><BR/>\n<P align=\"center\">Sergeant Major</P>\n<P align=\"center\">Master Sergeant</P>\n<P align=\"center\">Sergeant</P>\n<P align=\"center\">Corporal</P>\n<P align=\"center\">Private</P>\n</BODY>\n</HTML>",
      out = "<HTML>\n<BODY>\n<H1 align=\"center\">アライアンスの軍階級</H1><BR/>\n<P align=\"center\">士官</P><BR/>\n<P align=\"center\">グランド・マーシャル</P>\n<P align=\"center\">フィールド・マーシャル</P>\n<P align=\"center\">マーシャル</P>\n<P align=\"center\">コマンダー</P>\n<P align=\"center\">ルテナント・コマンダー</P>\n<P align=\"center\">ナイト・チャンピオン</P>\n<P align=\"center\">ナイト・キャプテン</P>\n<P align=\"center\">ナイト・ルテナント</P>\n<P align=\"center\">ナイト</P><BR/>\n<P align=\"center\">下士官・兵</P><BR/>\n<P align=\"center\">サージェント・メジャー</P>\n<P align=\"center\">マスター・サージェント</P>\n<P align=\"center\">サージェント</P>\n<P align=\"center\">コーポラル</P>\n<P align=\"center\">プライベート</P>\n</BODY>\n</HTML>" },
    { id = "book:2856:text", html = true,
      ja = "<HTML>\n<BODY>\n<H1 align=\"center\">ALLIANCEの士官階級</H1><BR/>\n<P align=\"center\">第2部</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>\n<P align=\"right\">騎士長</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>\n<P align=\"right\">騎士隊長</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>\n<P align=\"right\">騎士副官</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>\n<P align=\"right\">騎士</P><BR/><BR/>\n</BODY>\n</HTML>",
      out = "<HTML>\n<BODY>\n<H1 align=\"center\">アライアンスの士官階級</H1><BR/>\n<P align=\"center\">第2部</P>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>\n<P align=\"right\">騎士長</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>\n<P align=\"right\">騎士隊長</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>\n<P align=\"right\">騎士副官</P><BR/><BR/>\n<IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>\n<P align=\"right\">騎士</P><BR/><BR/>\n</BODY>\n</HTML>" },
    { id = "book:287:text", html = false,
      ja = "Kurdran Wildhammer\n\n名高きDragon Fighter。Aerie PeakのGryphon使いの達人。Draenorというオークの故郷へ進軍したAlliance Expeditionに属するGryphon Rider Divisionの司令官。死亡したものと推定される。\n\n我らは風に乗るSky-Reeの呼び声を聞くだろう。山々の頂に轟くそなたの槌の音を聞くだろう。来世へと力強く駆けよ、兄弟。我らが祖先の館がそなたを待っている。\n\n- Falstad Wildhammer - Aerie Peakの主",
      out = "カードラン・ワイルドハンマー\n\n名高きドラゴン・ファイター。エアリー・ピークのグリフォン使いの達人。ドレナーというオークの故郷へ進軍したアライアンス・エクスペディションに属するグリフォン・ライダー・ディビジョンの司令官。死亡したものと推定される。\n\n我らは風に乗るスカイ・リーの呼び声を聞くだろう。山々の頂に轟くそなたの槌の音を聞くだろう。来世へと力強く駆けよ、兄弟。我らが祖先の館がそなたを待っている。\n\n- ファルスタッド・ワイルドハンマー - エアリー・ピークの主" },
    { id = "book:405:text", html = false,
      ja = "いずれにせよ、彼は計画の実現にある程度成功したらしい。我が同胞に試す前に、まずfurbolgで企てを試そうとしたのだろうか？ furbolgが、彼の欲しがる何かを持っていたのだろうか？ 誰にも分からない。\n\n自ら作った品(何かの杖か棒のようなもの)を使って、彼はAshenvaleのfurbolgの部族に入り込もうとした。ある時点で、ここがまだ詳しく分かっていないところなのだが、furbolgを操って行動させようとしていたところを、彼は彼らに見破られた。その行動が向けられていた相手は",
      out = "いずれにせよ、彼は計画の実現にある程度成功したらしい。我が同胞に試す前に、まずファーボルグで企てを試そうとしたのだろうか？ ファーボルグが、彼の欲しがる何かを持っていたのだろうか？ 誰にも分からない。\n\n自ら作った品(何かの杖か棒のようなもの)を使って、彼はアッシェンヴェイルのファーボルグの部族に入り込もうとした。ある時点で、ここがまだ詳しく分かっていないところなのだが、ファーボルグを操って行動させようとしていたところを、彼は彼らに見破られた。その行動が向けられていた相手は" },
    { id = "book:711:text", html = false,
      ja = "Helgrumへ\n\nわれらの拠点KargathをBadlandsに築くよう命令を出した者に賛辞を送る。兵を鍛えるには理想的な場所だ。過酷な天候、凶暴な野生動物、好戦的な先住民、そして外部からの支援が一切ないこと。ここは、最も優れたウォリアーと斥候だけが生き残って出てくる、るつぼだ。\n\n良い計画だ。よくやった。",
      out = "ヘルグラムへ\n\nわれらの拠点カーガスをバッドランズに築くよう命令を出した者に賛辞を送る。兵を鍛えるには理想的な場所だ。過酷な天候、凶暴な野生動物、好戦的な先住民、そして外部からの支援が一切ないこと。ここは、最も優れたウォリアーと斥候だけが生き残って出てくる、るつぼだ。\n\n良い計画だ。よくやった。" },
    { id = "gossip:0310089941202749:text", html = false,
      ja = "また商売人かい？ オークションハウスならTrade Districtにあるよ。銀行からそう遠くない。",
      out = "また商売人かい？ オークションハウスならトレード・ディストリクトにあるよ。銀行からそう遠くない。" },
    { id = "gossip:0908aaec8e8621a9:text", html = false,
      ja = "余分な物資はあるが、多くはない。Field of Strifeへ地上攻撃を仕掛けるには、もっとたくさん必要だ。",
      out = "余分な物資はあるが、多くはない。フィールド・オブ・ストライフへ地上攻撃を仕掛けるには、もっとたくさん必要だ。" },
    { id = "gossip:0f54f777f3ca777f:text", html = false,
      ja = "えっと……悪いけど、あなたのことはよく知らないんだ。つまり、公認のMechano-strider販売業者として、ノームの友と認められた人にしか乗り物を売れないんだよ。もしGnomereganに友好的だと認められたら、喜んで品揃えを見せるよ。",
      out = "えっと……悪いけど、あなたのことはよく知らないんだ。つまり、公認のメカーノ・ストライダー販売業者として、ノームの友と認められた人にしか乗り物を売れないんだよ。もしノームリガンに友好的だと認められたら、喜んで品揃えを見せるよ。" },
    { id = "gossip:15e7c7c8851ddbd7:text", html = false,
      ja = "GadgetzanのDirge Quikcleaveは料理の達人だ。腕を磨きたいなら、彼を訪ねる必要がある。",
      out = "ガジェッツァンのダージ・クイッククリーヴは料理の達人だ。腕を磨きたいなら、彼を訪ねる必要がある。" },
    { id = "gossip:1bec2b7812418866:text", html = false,
      ja = "跪け、定命の者よ！Zodの前に跪け！",
      out = "跪け、定命の者よ！ゾッドの前に跪け！" },
    { id = "gossip:22327c8140ad6b95:text", html = false,
      ja = "担当者に嫌がらせをしたりチャンネルでスパムをしたりすると、アカウントがキック、BANされるか、それ以上の処分を受けることがあります。",
      out = "担当者に嫌がらせをしたりチャンネルでスパムをしたりすると、アカウントがキック、バンされるか、それ以上の処分を受けることがあります。" },
    { id = "gossip:27972b648119456d:text", html = false,
      ja = "Zul'Farrak - Sergeant Bly - デフォルトの挨拶。",
      out = "ズル・ファラック - サージェント・ブライ - デフォルトの挨拶。" },
    { id = "gossip:2e9474975033913b:text", html = false,
      ja = "Elder High Mountainはどこですか？",
      out = "エルダー・ハイ・マウンテンはどこですか？" },
    { id = "gossip:3401e97ab1efa1a7:text", html = false,
      ja = "Maywiki、Zandalar Haruspex's Beltをなくしてしまった。助けてもらえないか?",
      out = "メイウィキ、ザンダラー・ハルスペクセズ・ベルトをなくしてしまった。助けてもらえないか?" },
    { id = "gossip:399635fb3fadb3d4:text", html = false,
      ja = "Defias Brotherhoodの名のもとに死ね！",
      out = "デファイアス・ブラザーフッドの名のもとに死ね！" },
    { id = "gossip:3f35f225e1f5991c:text", html = false,
      ja = "ああ、お前が探しているシャーマンなら見たぞ。最後に見たときは、ここから西にいた。Razormane族の住処を見下ろす丘に隠れている。頭を使えば、丘の上にある彼女の小屋への道が見つかるはずだ。ここからそう遠くない北にある。その道を行けば、quilboarと戦わずに彼女のもとへたどり着けるだろう。",
      out = "ああ、お前が探しているシャーマンなら見たぞ。最後に見たときは、ここから西にいた。レイザーメイン族の住処を見下ろす丘に隠れている。頭を使えば、丘の上にある彼女の小屋への道が見つかるはずだ。ここからそう遠くない北にある。その道を行けば、キルボアと戦わずに彼女のもとへたどり着けるだろう。" },
    { id = "gossip:455b945896d6dbca:text", html = false,
      ja = "{name}、何をぐずぐずしている? Field of StrifeにいるField Marshalを見つけ、突撃命令を渡すのだ。命令を受け取れば、Field Marshalとその部隊はHordeに突撃し、捕虜など取らずに叩き潰すだろう!",
      out = "{name}、何をぐずぐずしている? フィールド・オブ・ストライフにいるフィールド・マーシャルを見つけ、突撃命令を渡すのだ。命令を受け取れば、フィールド・マーシャルとその部隊はホードに突撃し、捕虜など取らずに叩き潰すだろう!" },
    { id = "gossip:4af1b1c86d32f8ac:text", html = false,
      ja = "AzsharaでScourgeの侵食が広がっている。奴らの侵攻の流れを食い止めるには、戦える体を持つウォリアーが一人残らず必要だ。\n\n残っているNecropolisの数: $2279W",
      out = "アズシャラでスコージの侵食が広がっている。奴らの侵攻の流れを食い止めるには、戦える体を持つウォリアーが一人残らず必要だ。\n\n残っているネクロポリスの数: $2279W" },
    { id = "gossip:51de421e91ef1104:text", html = false,
      ja = "我が魂と亡骸は、長きにわたりこのMaraudonに囚われてきた、若き{class}よ。その時は、ただ己の過ちを省み、Remulosへの嫉妬が愚かであったと悟る機会を十分に与えてくれただけであった。彼はTheradrasとの関係からは清らかなものは何も生まれぬ――混沌からは破壊しか生まれぬと、我に警告し、説き伏せようとしたのだ。兄の言うとおりであった。\n\nだが、そなたが我を解き放ったからといって、我が償いから解き放たれたわけではない。",
      out = "我が魂と亡骸は、長きにわたりこのマラウドンに囚われてきた、若き{class}よ。その時は、ただ己の過ちを省み、レムロスへの嫉妬が愚かであったと悟る機会を十分に与えてくれただけであった。彼はセラドラスとの関係からは清らかなものは何も生まれぬ――混沌からは破壊しか生まれぬと、我に警告し、説き伏せようとしたのだ。兄の言うとおりであった。\n\nだが、そなたが我を解き放ったからといって、我が償いから解き放たれたわけではない。" },
    { id = "gossip:58087a20a01cc36e:text", html = false,
      ja = "気をつけろ、{class}。WindshapersはHigh Orderからの敵意を許しはしない。",
      out = "気をつけろ、{class}。ウィンドシェイパーはハイ・オーダーからの敵意を許しはしない。" },
    { id = "gossip:5e59f49174ee62b3:text", html = false,
      ja = "Razor Hillの東側にある兵舎の中にいるTarshaw Jaggedscarを探せ。Hordeに誇りと名誉をもたらすのだ、若造!",
      out = "レイザー・ヒルの東側にある兵舎の中にいるターショー・ジャギッドスカーを探せ。ホードに誇りと名誉をもたらすのだ、若造!" },
    { id = "gossip:63a2eed0217e73f1:text", html = false,
      ja = "すべて集まり、Silithusへ送られているところです、{class}。$2113w日以内に届くはずです。銅鑼が鳴らされ、門が開かれた後、ここでの私たちの努力が効果を上げ、多くの命を救うことをただ願うばかりです。",
      out = "すべて集まり、シリサスへ送られているところです、{class}。$2113w日以内に届くはずです。銅鑼が鳴らされ、門が開かれた後、ここでの私たちの努力が効果を上げ、多くの命を救うことをただ願うばかりです。" },
    { id = "gossip:69baad7508e8c38a:text", html = false,
      ja = "ごきげんよう、定命の者たちよ！我はDiscs of Norgannonにより起動され、そなたらを助けに参った！",
      out = "ごきげんよう、定命の者たちよ！我はディスク・オブ・ノルガノンにより起動され、そなたらを助けに参った！" },
    { id = "gossip:6f666d665bc06fae:text", html = false,
      ja = "ごきげんよう、{name}。Eluneの知恵があなたの手と心を導きますように。今日はどのようなご用件でしょう？",
      out = "ごきげんよう、{name}。エルーンの知恵があなたの手と心を導きますように。今日はどのようなご用件でしょう？" },
    { id = "gossip:752add1b487c18eb:text", html = false,
      ja = "我のみが……この務め……Windlordが……我らの声……彼は来る……失敗は許されぬ！",
      out = "我のみが……この務め……ウィンドロードが……我らの声……彼は来る……失敗は許されぬ！" },
    { id = "gossip:7a4ba35becc5d59e:text", html = false,
      ja = "すまんな、若いの。お前さんはまだわしから学ぶ域には達しとらん。息子のGroumのところへ行ってみな。新しい弟子ができれば、あいつも大喜びだろうよ。",
      out = "すまんな、若いの。お前さんはまだわしから学ぶ域には達しとらん。息子のグルームのところへ行ってみな。新しい弟子ができれば、あいつも大喜びだろうよ。" },
    { id = "gossip:805fe3b2b39ca71a:text", html = false,
      ja = "残念、必要なmageweave bandagesはもう全部集まったみたい。オークションハウスで売ってみたらどう? でも行く前に、いい子だから他の収集係にも声をかけてみて。何かお使いを頼まれるかもしれないよ。",
      out = "残念、必要なメイジウィーブ・バンデージはもう全部集まったみたい。オークションハウスで売ってみたらどう? でも行く前に、いい子だから他の収集係にも声をかけてみて。何かお使いを頼まれるかもしれないよ。" },
    { id = "gossip:876a22d5942b22ac:text", html = false,
      ja = "Razor Hillにある大きな建物で、兵舎じゃないほうだ。中にいるInnkeeper Groskに話しかけるだけでいい。わかったか?",
      out = "レイザー・ヒルにある大きな建物で、兵舎じゃないほうだ。中にいるインキーパー・グロスクに話しかけるだけでいい。わかったか?" },
    { id = "gossip:8ceaba8e021408ad:text", html = false,
      ja = "乳を搾ってくれ、John。",
      out = "乳を搾ってくれ、ジョン。" },
    { id = "gossip:937ead45abbc583d:text", html = false,
      ja = "Argent Dawnは、我らの大義のために身を捧げる意志のある者を誰一人拒みはしない。",
      out = "アージェント・ドーンは、我らの大義のために身を捧げる意志のある者を誰一人拒みはしない。" },
    { id = "gossip:98e3d2c218fea9b9:text", html = false,
      ja = "すまんな、若いの。お前にはまだ、わしが教えることを学ぶだけの基礎が足りん。でも気にするな、わしの弟子のRotgathと話してみろ。あいつが手を貸してくれるさ。",
      out = "すまんな、若いの。お前にはまだ、わしが教えることを学ぶだけの基礎が足りん。でも気にするな、わしの弟子のロトガスと話してみろ。あいつが手を貸してくれるさ。" },
    { id = "gossip:9ef0022309174478:text", html = false,
      ja = "守護者たちよ！Sen'jinを守れ！",
      out = "守護者たちよ！センジンを守れ！" },
    { id = "gossip:a4cc040b853164ba:text", html = false,
      ja = "俺ら、Tanarisのogreどもよりずっと綺麗だぞ。砂漠中、見渡す限り、ogreのフンだらけ。ここは違う、絶対違うぞ、お客さん！",
      out = "俺ら、タナリスのオーガどもよりずっと綺麗だぞ。砂漠中、見渡す限り、オーガのフンだらけ。ここは違う、絶対違うぞ、お客さん！" },
    { id = "gossip:aaa7e8aabec4f64d:text", html = false,
      ja = "我は蘇るぞ、定命の者どもよ！Incendiusがこの灰から我を甦らせるのだ！",
      out = "我は蘇るぞ、定命の者どもよ！インセンディウスがこの灰から我を甦らせるのだ！" },
    { id = "gossip:b0cfab88f36b6ab9:text", html = false,
      ja = "Allianceが製材所を奪った！",
      out = "アライアンスが製材所を奪った！" },
    { id = "gossip:b66ec1a413f3cf23:text", html = false,
      ja = "私の知識は限られている。まだ学んでいる身だからな。お前が次へ進む時だ、旅人よ。UndercityにいるJosef Gregorianを見つけ、準備ができたと伝えろ。",
      out = "私の知識は限られている。まだ学んでいる身だからな。お前が次へ進む時だ、旅人よ。アンダーシティにいるヨーゼフ・グレゴリアンを見つけ、準備ができたと伝えろ。" },
    { id = "gossip:bc2ee1fbb7dbff09:text", html = false,
      ja = "その通りだ、{name}。破滅の歯車は今や、避けがたくHakkarの真の復活へと回っている！",
      out = "その通りだ、{name}。破滅の歯車は今や、避けがたくハッカーの真の復活へと回っている！" },
    { id = "gossip:c316bf425049b5c0:text", html = false,
      ja = "余剰の物資はほとんど残っていない。Field of Strifeへ再び地上部隊を送り込む準備が整うまでには、まだ相当な働きが必要だ。",
      out = "余剰の物資はほとんど残っていない。フィールド・オブ・ストライフへ再び地上部隊を送り込む準備が整うまでには、まだ相当な働きが必要だ。" },
    { id = "gossip:c94fa0daa306db84:text", html = false,
      ja = "危害を加えに来たのではない、Kharan。Gor'shakに遣わされて来たのだ。あなたがPrincessについて話してくれると、彼は言っていた。",
      out = "危害を加えに来たのではない、カラン。ゴーシャクに遣わされて来たのだ。あなたがプリンセスについて話してくれると、彼は言っていた。" },
    { id = "gossip:cff6852b997e52d9:text", html = false,
      ja = "Tear of the Moonsの力は私のものだ！私のものだと言っているのだ！",
      out = "ティア・オブ・ザ・ムーンの力は私のものだ！私のものだと言っているのだ！" },
    { id = "gossip:d57a4e71d2fc0079:text", html = false,
      ja = "ようやくか！耳に指でも突っ込んでおけ、お前の脳みそが今しがた5倍に膨らんだかもしれん、漏れ出さんか心配だ。\n\nで、Dark Ironsは奴の命を助けて捕虜にした。奴らの頭目、Thauris-somethingとかいう偉そうで気取った野郎が、Ironfoeを自分のものにしちまった。それが懐かしいWindsorを見た最後さ……*ヒック* 失礼。",
      out = "ようやくか！耳に指でも突っ込んでおけ、お前の脳みそが今しがた5倍に膨らんだかもしれん、漏れ出さんか心配だ。\n\nで、ダーク・アイアンは奴の命を助けて捕虜にした。奴らの頭目、ソーリス・サムシングとかいう偉そうで気取った野郎が、アイアンフォーを自分のものにしちまった。それが懐かしいウィンザーを見た最後さ……*ヒック* 失礼。" },
    { id = "gossip:dbbff4dda8a48e72:text", html = false,
      ja = "俺が乗騎を譲るのは、Orgrimmarとオークの種族から崇敬されていると認められた者だけだ。我々に己を証明してみせろ。そうすれば、我が強き狼どもを検分させてやろう。",
      out = "俺が乗騎を譲るのは、オーグリマーとオークの種族から崇敬されていると認められた者だけだ。我々に己を証明してみせろ。そうすれば、我が強き狼どもを検分させてやろう。" },
    { id = "gossip:e197ef677dfef050:text", html = false,
      ja = "こんにちは、{name}。私はChronormuという名で知られているけれど、Chromieと呼んでくれてかまわないよ。そういう気安さは嫌いじゃないんだ。\n\nさて——どうして私が君の名前を知っていたのか、だって？私はbronze dragonflightの一員で、常に時の満ち引きと結ばれているのさ。私たちは以前に会ったことがある、と言ってもいい。そして同じように、また会うことにもなる。\n\nこの姿を選んだことで君を不安にさせていなければいいのだけれど。悲しみに満ちた場所の見張りを任された身とはいえ、私はその土地の悲しみに沈まないことにしているんだ。",
      out = "こんにちは、{name}。私はクロノルムという名で知られているけれど、クロミーと呼んでくれてかまわないよ。そういう気安さは嫌いじゃないんだ。\n\nさて——どうして私が君の名前を知っていたのか、だって？私はブロンズ・ドラゴンフライトの一員で、常に時の満ち引きと結ばれているのさ。私たちは以前に会ったことがある、と言ってもいい。そして同じように、また会うことにもなる。\n\nこの姿を選んだことで君を不安にさせていなければいいのだけれど。悲しみに満ちた場所の見張りを任された身とはいえ、私はその土地の悲しみに沈まないことにしているんだ。" },
    { id = "gossip:e7e95f422aef9215:text", html = false,
      ja = "ドワーフどもときたら、採掘のやり方を教えるためにIronforgeから鉱山の専門家を送り込んでくるんだからな。つるはしを持って岩を削るのがそんなに難しいか? まあ、せっかく来ているんだ、どうせ会うべき相手は彼なんだろう。名はGelman、Dwarven Districtにいる。",
      out = "ドワーフどもときたら、採掘のやり方を教えるためにアイアンフォージから鉱山の専門家を送り込んでくるんだからな。つるはしを持って岩を削るのがそんなに難しいか? まあ、せっかく来ているんだ、どうせ会うべき相手は彼なんだろう。名はゲルマン、ドワーベン・ディストリクトにいる。" },
    { id = "gossip:ee4a596ce4831051:text", html = false,
      ja = "nagaを狩ろうというのなら、得られる助けはすべて必要になるだろう。水の深いところには、水中でも息ができるだけの気泡を噴き出す裂け目がある。その泡を使えるよう、近くまで泳いでいくといい。",
      out = "ナーガを狩ろうというのなら、得られる助けはすべて必要になるだろう。水の深いところには、水中でも息ができるだけの気泡を噴き出す裂け目がある。その泡を使えるよう、近くまで泳いでいくといい。" },
    { id = "gossip:f4aea43239c595e5:text", html = false,
      ja = "Athrikusが私たちのもとへ来たのです。災いから救ってやれると言いました。そして災いから守るという呪文を私たちにかけたのです。",
      out = "アスリカスが私たちのもとへ来たのです。災いから救ってやれると言いました。そして災いから守るという呪文を私たちにかけたのです。" },
    { id = "gossip:fb273d278a2d9e68:text", html = false,
      ja = "AshenvaleのZoram Strandに位置するBlackfathom Deepsは、かつてナイトエルフの月の女神Eluneに捧げられた壮麗な神殿だった。しかし大いなるSunderingが神殿を砕き、Veiled Seaの波の下へと沈めてしまった。そこで神殿は手つかずのまま残されていた――やがてその古の力に引き寄せられ、nagaとsatyrが秘密を探ろうと現れるまでは。伝承によれば、古の獣Aku'maiがその神殿の廃墟に住み着いているという。",
      out = "アッシェンヴェイルのゾラム・ストランドに位置するブラックファゾム・ディープは、かつてナイトエルフの月の女神エルーンに捧げられた壮麗な神殿だった。しかし大いなるサンダリングが神殿を砕き、ヴェイルド・シーの波の下へと沈めてしまった。そこで神殿は手つかずのまま残されていた――やがてその古の力に引き寄せられ、ナーガとセイターが秘密を探ろうと現れるまでは。伝承によれば、古の獣アクマイがその神殿の廃墟に住み着いているという。" },
    { id = "item:10323:description", html = false,
      ja = "Tuxedo Pantsの縫い方を習得します。",
      out = "タキシード・パンツの縫い方を習得します。" },
