    { id = "item:219974:description", html = false,
      ja = "このメッセージは、受け取ると自動的に消滅する。Field Captainはあなたの行動について一切関知しない。",
      out = "このメッセージは、受け取ると自動的に消滅する。フィールド・キャプテンはあなたの行動について一切関知しない。" },
    { id = "item:22123:description", html = false,
      ja = "5枚集めるとOrgrimmar Pledge \nCollectionになります。",
