    { id = "item:22297:description", html = false,
      ja = "Basket of Flowers・Satchel of \nCards・Thunder Bluff Pledge \nCollectionを集めるとThunder Bluff \nGift Collectionになります。",
      out = "バスケット・オブ・フラワー・サッチェル・オブ \nカード・サンダー・ブラフ・プレッジ \nコレクションを集めるとサンダー・ブラフ \nギフト・コレクションになります。" },
    { id = "item:22683:description", html = false,
      ja = "Gaea's Embraceの縫い方を習得します。",
      out = "ガイアズ・エンブレイスの縫い方を習得します。" },
    { id = "item:227685:description", html = false,
      ja = "Modified Shadow ScalpelをArkonos the Cursedに向けて集中させ、彼を守る障壁を解除します。\nCuthbertがこの器具にRowanの最後の祝福を授けました。これでArkonosを守る障壁を解くことができるはずです。",
      out = "モディファイド・シャドウ・スカルペルをアーコノス・ザ・カースドに向けて集中させ、彼を守る障壁を解除します。\nカスバートがこの器具にローワンの最後の祝福を授けました。これでアーコノスを守る障壁を解くことができるはずです。" },
    { id = "item:231566:description", html = false,
      ja = "すべての呪文と攻撃のクリティカル率を$N1%上昇させます。\nAttack Powerが$N2上昇します。",
      out = "すべての呪文と攻撃のクリティカル率を$N1%上昇させます。\nアタック・パワーが$N2上昇します。" },
    { id = "item:23456:description", html = false,
      ja = "クリティカル率を$N1%上昇させます。\nAttack Powerが$N2上昇します。",
      out = "クリティカル率を$N1%上昇させます。\nアタック・パワーが$N2上昇します。" },
    { id = "item:239531:description", html = false,
      ja = "すべての呪文と攻撃のクリティカル率を$N1%上昇させます。\n攻撃が回避または受け流される確率を$N2%低下させます。\nAttack Powerが$N3上昇します。",
      out = "すべての呪文と攻撃のクリティカル率を$N1%上昇させます。\n攻撃が回避または受け流される確率を$N2%低下させます。\nアタック・パワーが$N3上昇します。" },
