    { id = "item:4370:description", html = false,
      ja = "半径$N2ヤード内の対象に$N1のFireダメージを与え、$D1スタンさせます。ダメージを受けると効果は解除されます。",
      out = "半径$N2ヤード内の対象に$N1のファイアダメージを与え、$D1スタンさせます。ダメージを受けると効果は解除されます。" },
    { id = "item:5648:description", html = false,
      ja = "Frost Armor（Rank $N1）を習得します。",
      out = "フロスト・アーマー（ランク $N1）を習得します。" },
    { id = "item:6621:description", html = false,
      ja = "Taunt（Rank $N1）を習得します。",
