    { id = "item:7992:description", html = false,
      ja = "Blue Glittering Axeの作り方を習得します。",
      out = "ブルー・グリッタリング・アックスの作り方を習得します。" },
    { id = "item:8823:description", html = false,
      ja = "Fire Blast（Rank $N1）を習得します。",
