    { id = "item:8990:description", html = false,
      ja = "Prayer of Healing（Rank $N1）を習得します。",
      out = "プレイヤー・オブ・ヒーリング（ランク $N1）を習得します。" },
    { id = "item:9164:description", html = false,
      ja = "Lightning Shield（Rank $N1）を習得します。",
      out = "ライトニング・シールド（ランク $N1）を習得します。" },
    { id = "item:973:description", html = false,
      ja = "Fireball（Rank 2）を習得します。",
      out = "ファイアボール（ランク 2）を習得します。" },
    { id = "objective:384077:text", html = false,
      ja = "Lumber Millを襲撃する",
      out = "ランバー・ミルを襲撃する" },
    { id = "objective:470255:text", html = false,
      ja = "Tazzikと対決する",
      out = "タズィックと対決する" },
    { id = "objective:476601:text", html = false,
      ja = "First Aidのスキルを20まで上げる",
      out = "ファースト・エイドのスキルを20まで上げる" },
    { id = "quest:1017:description", html = false,
      ja = "Barrensでこれほど多くの水のエレメンタルを穢せるアンデッドのメイジは一人しかいない。そんなことを試みるほど愚かなのも奴だけだ。Sarilus Foulborneは、おそらくDreadmist Peakの頂上に座って私を笑っているのだろう。\n\n{name}、敵地へ乗り込み、この悪党を始末してくれ。奴の愚行にはもううんざりだ。Sentinelsを怒らせた者がどうなるか、思い知らせてやらねばならない。\n\n奴を倒し、首を持ってくるのだ。だが用心しろ、Hordeが君を見張っているかもしれない。",
      out = "バレンズでこれほど多くの水のエレメンタルを穢せるアンデッドのメイジは一人しかいない。そんなことを試みるほど愚かなのも奴だけだ。サリラス・ファウルボーンは、おそらくドレッドミスト・ピークの頂上に座って私を笑っているのだろう。\n\n{name}、敵地へ乗り込み、この悪党を始末してくれ。奴の愚行にはもううんざりだ。センチネルを怒らせた者がどうなるか、思い知らせてやらねばならない。\n\n奴を倒し、首を持ってくるのだ。だが用心しろ、ホードが君を見張っているかもしれない。" },
    { id = "quest:1050:completion", html = false,
      ja = "聖なる書を救い出してくれたのか！\n\n長い旅だっただろうし、あの本を手に入れるのは決して容易な務めではなかったに違いない。だがお前の成功で、Ironforgeのドワーフたちは恩恵を受けるだろう。\n\nExplorers' Leagueを代表して礼を言うぞ、{name}。",
      out = "聖なる書を救い出してくれたのか！\n\n長い旅だっただろうし、あの本を手に入れるのは決して容易な務めではなかったに違いない。だがお前の成功で、アイアンフォージのドワーフたちは恩恵を受けるだろう。\n\nエクスプローラー・リーグを代表して礼を言うぞ、{name}。" },
    { id = "quest:1084:objectives", html = false,
      ja = "Corroded Shrapnelの破片を一つ、StonetalonのKaela Shadowspearのところへ持って行って下さい。",
      out = "コローデッド・シュラプネルの破片を一つ、ストーンタロンのケイラ・シャドウスピアのところへ持って行って下さい。" },
    { id = "quest:1119:title", html = false,
      ja = "Zanzil's MixtureとFool's Stout",
      out = "ザンジルズ・ミクスチャーとフールズ・スタウト" },
    { id = "quest:1160:completion", html = false,
      ja = "お前に探すように遣わした本だな。\n\n<Parqualは本を見下ろしながら、表紙をゆっくり撫でた。>\n\n体と精神と同じく心も力に溢れていると証明すべく、問いを望んでいるのだな。この本をじっくりと読みこなしたならば、問いを出そう。そして、お前は試しを終えることができるのだ!",
      out = "お前に探すように遣わした本だな。\n\n<パークアルは本を見下ろしながら、表紙をゆっくり撫でた。>\n\n体と精神と同じく心も力に溢れていると証明すべく、問いを望んでいるのだな。この本をじっくりと読みこなしたならば、問いを出そう。そして、お前は試しを終えることができるのだ!" },
    { id = "quest:1202:description", html = false,
      ja = "{name}、我々の密偵2人が、Theramoreの波止場に停泊する船から書類を盗み出すために送り込まれた。書類は手に入れたが見つかってしまい、書類を海へ投げ捨てるしかなかった。\n\n密偵の1人は後に逃げ延びたが、獲物を取り戻すことはできなかった。彼は私に失敗を報告した。そこで今、この任務を君に任せる。\n\n書類はTheramoreの波止場の下、水中のどこかにある収納箱の中だ。その書類を見つけ出し、私のもとへ持ってこい、{name}。",
      out = "{name}、我々の密偵2人が、セラモアの波止場に停泊する船から書類を盗み出すために送り込まれた。書類は手に入れたが見つかってしまい、書類を海へ投げ捨てるしかなかった。\n\n密偵の1人は後に逃げ延びたが、獲物を取り戻すことはできなかった。彼は私に失敗を報告した。そこで今、この任務を君に任せる。\n\n書類はセラモアの波止場の下、水中のどこかにある収納箱の中だ。その書類を見つけ出し、私のもとへ持ってこい、{name}。" },
    { id = "quest:1268:objectives", html = false,
      ja = "Shady Rest Innの怪しい足跡について、Brackenwall VillageのKrogに報告して下さい。",
      out = "シェイディ・レスト・インの怪しい足跡について、ブラッケンウォール・ヴィレッジのクロッグに報告して下さい。" },
    { id = "quest:1361:objectives", html = false,
      ja = "Regthar Deathgateと話して下さい。",
      out = "レグサー・デスゲートと話して下さい。" },
    { id = "quest:1418:completion", html = false,
      ja = "Helgrumが報告を欲しがっているだと？3日も経たぬ前に伝令をStonardへ送ったぞ。任務に失敗したのか？Stonardに私の報告が届いていないなら、失敗したようだな。\n\n次に送る伝令が、もっと腕が立つか、もっと運が良いことを願おう。",
      out = "ヘルグラムが報告を欲しがっているだと？3日も経たぬ前に伝令をストナードへ送ったぞ。任務に失敗したのか？ストナードに私の報告が届いていないなら、失敗したようだな。\n\n次に送る伝令が、もっと腕が立つか、もっと運が良いことを願おう。" },
    { id = "quest:1453:description", html = false,
      ja = "Desolace にやらねばならん仕事があるのだ、{name} 。あそこはcentaurやその他の汚らわしいもので汚されたひどい場所だ。だが、正味一週間分ある仕事を探しておるんなら、あそこへ行って Kreldig Ungor に会ってわしに寄越されたと伝えろ。\n\nあいつは Nijel's Point にこもっとるはず―― Desolace 北部の山中に隠された居心地のいい小さなキャンプだよ。Stonetalon Mountains から入れば、東に向かうだけだ。見逃しやすいから、注意して探すのだぞ。",
      out = "デソレース にやらねばならん仕事があるのだ、{name} 。あそこはセントールやその他の汚らわしいもので汚されたひどい場所だ。だが、正味一週間分ある仕事を探しておるんなら、あそこへ行って クレルディグ・アンゴル に会ってわしに寄越されたと伝えろ。\n\nあいつは ナイジェルズ・ポイント にこもっとるはず―― デソレース 北部の山中に隠された居心地のいい小さなキャンプだよ。ストーンタロン・マウンテン から入れば、東に向かうだけだ。見逃しやすいから、注意して探すのだぞ。" },
    { id = "quest:1488:objectives", html = false,
      ja = "Lord AzrethocとJugkar Grim'rodを倒し、DesolaceのTakata Steelbladeのところへ戻って下さい。",
      out = "ロード・アズレソックとジャグカー・グリムロッドを倒し、デソレースのタカタ・スティールブレードのところへ戻って下さい。" },
    { id = "quest:1530:description", html = false,
      ja = "水について学ばねばならない教えが一つあるとすれば、それはこれです。水とは再生を意味するのです。\n\n水の力は流れ、削り、あらゆるものを清めます。水の癒し、満たす力は比類ないものだと分かるでしょう。ただし、それは水が清らかなときだけです。\n\n水が汚れれば、触れるものすべてを荒廃させうる。そのことを理解したとき、水がどれほど欠かせない資源なのか分かるでしょう。\n\n水のsaptaを望むなら、Southern Barrensの奥深くにいるBrineを探しなさい。Brineの住まいは、あそこのquilboarに絶えず荒らされているのです。",
      out = "水について学ばねばならない教えが一つあるとすれば、それはこれです。水とは再生を意味するのです。\n\n水の力は流れ、削り、あらゆるものを清めます。水の癒し、満たす力は比類ないものだと分かるでしょう。ただし、それは水が清らかなときだけです。\n\n水が汚れれば、触れるものすべてを荒廃させうる。そのことを理解したとき、水がどれほど欠かせない資源なのか分かるでしょう。\n\n水のサプタを望むなら、サザン・バレンズの奥深くにいるブラインを探しなさい。ブラインの住まいは、あそこのキルボアに絶えず荒らされているのです。" },
    { id = "quest:1650:completion", html = false,
      ja = "こんにちは、{name}。その鎧と武器から察するに、あなたは私の土地を奪いに来たか、Jordanが留守の間に私を守るためにChurchがようやく誰かを寄越したかのどちらかね。\n\nでは自己紹介させて。私はDaphne Stilwell。よろしくね。\n\nまだ遅くはないわ……日が昇ってからは、あのクズどもを半ダースほど殺しただけ。向こうの曲がり角を回ってくるのが少し遅れているけれど、たぶんあなたが来るのが見えたんでしょう。つまり、もうすぐここに現れるってことよ。",
      out = "こんにちは、{name}。その鎧と武器から察するに、あなたは私の土地を奪いに来たか、ジョーダンが留守の間に私を守るためにチャーチがようやく誰かを寄越したかのどちらかね。\n\nでは自己紹介させて。私はダフネ・スティルウェル。よろしくね。\n\nまだ遅くはないわ……日が昇ってからは、あのクズどもを半ダースほど殺しただけ。向こうの曲がり角を回ってくるのが少し遅れているけれど、たぶんあなたが来るのが見えたんでしょう。つまり、もうすぐここに現れるってことよ。" },
    { id = "quest:1702:completion", html = false,
      ja = "おお、Barleybrew Scalderか。いい酒だ！ってことは、Yorusに会ってきたんだな？\n\n盾なら用意できるぜ、承知したよ、お客さん！これ以上の盾は見つからないぞ、嘘じゃない！",
      out = "おお、バーリーブルー・スカルダーか。いい酒だ！ってことは、ヨーラスに会ってきたんだな？\n\n盾なら用意できるぜ、承知したよ、お客さん！これ以上の盾は見つからないぞ、嘘じゃない！" },
    { id = "quest:1787:title", html = false,
      ja = "Tome of Divinity",
      out = "トーム・オブ・ディビニティ" },
    { id = "quest:1858:completion", html = false,
      ja = "ふーむ。これは面白いな。己の真価のみに留まらぬものをお前は示したのだ、{name}。実に感動した。お前はShattered Handの新人だと思え。それとこれを持って行け。後々、大いに役立つだろう。",
      out = "ふーむ。これは面白いな。己の真価のみに留まらぬものをお前は示したのだ、{name}。実に感動した。お前はシャッタード・ハンドの新人だと思え。それとこれを持って行け。後々、大いに役立つだろう。" },
    { id = "quest:1952:objectives", html = false,
      ja = "儀式の後、Tabethaと話して下さい。",
      out = "儀式の後、タベサと話して下さい。" },
    { id = "quest:211:progress", html = false,
      ja = "任務はもう与えたはずだ、{name}。任務を果たした証として、lichの魂の器の欠片を持っているか？",
      out = "任務はもう与えたはずだ、{name}。任務を果たした証として、リッチの魂の器の欠片を持っているか？" },
    { id = "quest:2260:objectives", html = false,
      ja = "Stormwind Cityへ行き、Renzik 'The Shiv'の助言を求めて下さい。",
      out = "ストームウィンド・シティへ行き、レンジック 'シヴ'の助言を求めて下さい。" },
    { id = "quest:239:description", html = false,
      ja = "西の境界線にあるGarrison地区から、gnollや盗賊が勢力を拡大してきているとの伝令が入った。同時に、援軍要請があったのだが、我々には余分な戦力などない！\n\nどうか援軍として、彼らのところに向かってほしい。Westbrook GarrisonにいるDeputy Rainerのところへ急ぎ、力を貸してやってほしいのだ。\n\nGarrisonへは、この道を西に進めば着く。小川にかかる橋を渡ったすぐ先がそうだ。",
      out = "西の境界線にあるギャリソン地区から、ノールや盗賊が勢力を拡大してきているとの伝令が入った。同時に、援軍要請があったのだが、我々には余分な戦力などない！\n\nどうか援軍として、彼らのところに向かってほしい。ウェストブルック・ギャリソンにいるデピュティ・レイナーのところへ急ぎ、力を貸してやってほしいのだ。\n\nギャリソンへは、この道を西に進めば着く。小川にかかる橋を渡ったすぐ先がそうだ。" },
    { id = "quest:2581:title", html = false,
      ja = "Snickerfang Jowls",
      out = "スニッカーファング・ジャウル" },
    { id = "quest:2747:progress", html = false,
      ja = "Feralasから並外れた状態で持ち帰られた卵は、ほとんど見たことがありません。これは最も珍しい種類の卵です……",
      out = "フェララスから並外れた状態で持ち帰られた卵は、ほとんど見たことがありません。これは最も珍しい種類の卵です……" },
    { id = "quest:282:description", html = false,
      ja = "報告書は弟子に持たせて兄弟のSenirに送るつもりだったが、もっと……信頼できる者の手に預けたほうがずっと安心できる。もちろん、君さえよければだが？\n\nふむ……Kharanosへ行くにはトンネルを通らねばならんな。\n\nトンネルを抜ける前にMountaineer Thalosと話しておけ。今あそこはtroggsだらけだ。\n\n道なりにAnvilmarまで戻って、そのまま東へトンネルまで進め。Thalosはその近くに配置されている。",
      out = "報告書は弟子に持たせて兄弟のセニアに送るつもりだったが、もっと……信頼できる者の手に預けたほうがずっと安心できる。もちろん、君さえよければだが？\n\nふむ……カラノスへ行くにはトンネルを通らねばならんな。\n\nトンネルを抜ける前にマウンテニア・サロスと話しておけ。今あそこはトログだらけだ。\n\n道なりにアンヴィルマーまで戻って、そのまま東へトンネルまで進め。サロスはその近くに配置されている。" },
    { id = "quest:2873:description", html = false,
      ja = "賭けの清算のために、Booty Bayの\"Sea Wolf\" MacKinleyにラム酒を借りてるんだが、ラム酒がすっかり切れちまったんだ！ Captain Cuergoの奴が俺の最後の積荷を盗んで、南にある壁に囲まれた海賊の町にしまい込んでやがる。\n\n俺のラム酒の積荷を見つけて持ち帰ってくれれば、Kalimdorの酒のほうがBooty Bayの酒よりもはるかに上だってことをMacKinleyに証明できるんだ！",
      out = "賭けの清算のために、ブーティ・ベイの\"シー・ウルフ\" マッキンリーにラム酒を借りてるんだが、ラム酒がすっかり切れちまったんだ！ キャプテン・クエルゴの奴が俺の最後の積荷を盗んで、南にある壁に囲まれた海賊の町にしまい込んでやがる。\n\n俺のラム酒の積荷を見つけて持ち帰ってくれれば、カリムドアの酒のほうがブーティ・ベイの酒よりもはるかに上だってことをマッキンリーに証明できるんだ！" },
    { id = "quest:2941:completion", html = false,
      ja = "君もDarynのインターンの一人かい? 彼女はとても博識な歴史家だよ、{name}。彼女の指導の下で学べることに感謝するべきだね。\n\nさて、Super Snapper FXを持ってこよう。きっと気に入るよ!",
      out = "君もダリンのインターンの一人かい? 彼女はとても博識な歴史家だよ、{name}。彼女の指導の下で学べることに感謝するべきだね。\n\nさて、スーパー・スナッパー・エフエックスを持ってこよう。きっと気に入るよ!" },
    { id = "quest:2983:description", html = false,
      ja = "前回試練を受けてからしばらく経つな、{name}。これまで修行に辛抱強く取り組んできたが、そろそろより大きな力について学ぶ時だ……真の力を学ぶ時だ。代価を払う覚悟があるなら、火の元素はお前のものだ。\n\nBarrensのKranal Fissを探せ。Crossroadsの北にある小さな住まいに住んでいる。だが気をつけろ、忌々しいナイトエルフの土地まで来てしまったら、行き過ぎだ。",
      out = "前回試練を受けてからしばらく経つな、{name}。これまで修行に辛抱強く取り組んできたが、そろそろより大きな力について学ぶ時だ……真の力を学ぶ時だ。代価を払う覚悟があるなら、火の元素はお前のものだ。\n\nバレンズのクラナル・フィスを探せ。クロスロードの北にある小さな住まいに住んでいる。だが気をつけろ、忌々しいナイトエルフの土地まで来てしまったら、行き過ぎだ。" },
    { id = "quest:3083:progress", html = false,
      ja = "Valley of Trialsへようこそ、{name}。俺のtabletを手に入れていなければ、お前はここにいないはずだ。だから単刀直入に言おう。\n\n俺はRwag、このValleyでローグ、盗賊、スリどもを鍛える役目を負っている。お前にこれから起こることへの備えができていなければ、Handが頼るのは俺だ。だが心配するな、Handがお前のやることを全部支配するわけじゃない。とはいえ、奴らがお前の才能を必要とするなら、手を組むのが賢明だろうな。",
      out = "バレー・オブ・トライアルへようこそ、{name}。俺のタブレットを手に入れていなければ、お前はここにいないはずだ。だから単刀直入に言おう。\n\n俺はルワグ、このバレーでローグ、盗賊、スリどもを鍛える役目を負っている。お前にこれから起こることへの備えができていなければ、ハンドが頼るのは俺だ。だが心配するな、ハンドがお前のやることを全部支配するわけじゃない。とはいえ、奴らがお前の才能を必要とするなら、手を組むのが賢明だろうな。" },
    { id = "quest:3113:title", html = false,
      ja = "Encrypted Memorandum",
      out = "エンクリプテッド・メモランダム" },
    { id = "quest:324:progress", html = false,
      ja = "必要なlightforge ironは見つかったか?",
      out = "必要なライトフォージ・アイアンは見つかったか?" },
    { id = "quest:338:description", html = false,
      ja = "Master Nesingwaryに知られたら、ひどく怒られちまう！\n\nあの人の小説、The Green Hills of Stranglethornの原稿の校正を任されてたんだ。順調だったのに、強い風が野営地を吹き抜けて、ページがあちこちに散らばっちまったんだよ！\n\nほとんどのページは集められたけど、まだたくさんジャングルに散らばってる。ページを集めて、四つの章をそれぞれ完成させてくれ。\n\n整理するのは手伝うよ。四つの章が全部そろったら、持ってきてくれ。",
      out = "マスター・ネッシングウェアリーに知られたら、ひどく怒られちまう！\n\nあの人の小説、グリーン・ヒル・オブ・ストラングルソーンの原稿の校正を任されてたんだ。順調だったのに、強い風が野営地を吹き抜けて、ページがあちこちに散らばっちまったんだよ！\n\nほとんどのページは集められたけど、まだたくさんジャングルに散らばってる。ページを集めて、四つの章をそれぞれ完成させてくれ。\n\n整理するのは手伝うよ。四つの章が全部そろったら、持ってきてくれ。" },
    { id = "quest:350:objectives", html = false,
      ja = "StormwindのElling Triasに話しかけて下さい。",
      out = "ストームウィンドのエリング・トライアスに話しかけて下さい。" },
    { id = "quest:3601:completion", html = false,
      ja = "ハハ! あいつらをうまくやっつけてくれたんだね?!\n\nこいつは最高だ! これで、あのBlood elvesどもも仲間を裏切るとどうなるか思い知るだろう……特にゴブリンの商人みたいに忠実な相手をね! ふん、Blood elvesめ……!\n\nさて、せめてもの礼に、あんたの時間の分は払わせてもらうよ……約束したとおりにね。\n\nほらよ……これは役に立つはずさ。",
      out = "ハハ! あいつらをうまくやっつけてくれたんだね?!\n\nこいつは最高だ! これで、あのブラッド・エルフどもも仲間を裏切るとどうなるか思い知るだろう……特にゴブリンの商人みたいに忠実な相手をね! ふん、ブラッド・エルフめ……!\n\nさて、せめてもの礼に、あんたの時間の分は払わせてもらうよ……約束したとおりにね。\n\nほらよ……これは役に立つはずさ。" },
    { id = "quest:3702:progress", html = false,
      ja = "Thaurissanの物語を最後まで話させてくれ。",
      out = "ソーリサンの物語を最後まで話させてくれ。" },
    { id = "quest:3822:progress", html = false,
      ja = "Sha'niを見つけてくれたか? 彼女は無事なのか?",
      out = "シャニを見つけてくれたか? 彼女は無事なのか?" },
    { id = "quest:3924:title", html = false,
      ja = "Samophlange Manual",
      out = "サモフランジ・マニュアル" },
    { id = "quest:4102:title", html = false,
      ja = "Felwoodの浄化",
      out = "フェルウッドの浄化" },
    { id = "quest:4143:description", html = false,
      ja = "正直なところ、{name}、旅の中でこんな植物は見たことがないよ。そのクレーターへ行ってみるべきかもしれないな……\n\nいずれにせよ、Muiginが探しているものはちょうど分かっていると思う――Atal'ai hazeだ。ひどい代物で、集めるのも大変だが、あの小さな怪物どもを操るにはまさにうってつけだ。\n\nSwamp of SorrowsにあるAtal'Hakkarの神殿へ行く必要がある。Atal'ai Hazeは、そこにいるdeep lurkers、murk worms、oozesから集められるよ。幸運を祈る、{name}！",
      out = "正直なところ、{name}、旅の中でこんな植物は見たことがないよ。そのクレーターへ行ってみるべきかもしれないな……\n\nいずれにせよ、ムイギンが探しているものはちょうど分かっていると思う――アタライ・ヘイズだ。ひどい代物で、集めるのも大変だが、あの小さな怪物どもを操るにはまさにうってつけだ。\n\nスワンプ・オブ・ソロウにあるアタルハッカーの神殿へ行く必要がある。アタライ・ヘイズは、そこにいるディープ・ラーカー、マーク・ワーム、ウーズから集められるよ。幸運を祈る、{name}！" },
    { id = "quest:4264:title", html = false,
      ja = "A Crumpled Up Note",
      out = "ア・クランプルド・アップ・ノート" },
    { id = "quest:437:objectives", html = false,
      ja = "Dead FieldsにおいてRot Hide Gnollを倒してください。\n\nNightlashが現れたら、彼女を倒してください。\n\nEssence of Nightlashを入手し、SepulcherのHigh Executor Hadrecに渡してください。",
      out = "デッド・フィールドにおいてロット・ハイド・ノールを倒してください。\n\nナイトラッシュが現れたら、彼女を倒してください。\n\nエッセンス・オブ・ナイトラッシュを入手し、セパルカーのハイ・エグゼキューター・ハドレクに渡してください。" },
    { id = "quest:4489:objectives", html = false,
      ja = "RatchetのStrahad Farsanと話して下さい。",
      out = "ラチェットのストラハド・ファーサンと話して下さい。" },
    { id = "quest:4601:progress", html = false,
      ja = "どうやらこの装置を動かすには、きれいにするための汚れのこびりついた品と、銀貨3枚が必要なようだ。その両方がそろっていれば、Sparklematic 5200は動くはずだ……",
      out = "どうやらこの装置を動かすには、きれいにするための汚れのこびりついた品と、銀貨3枚が必要なようだ。その両方がそろっていれば、スパークルマティック 5200は動くはずだ……" },
    { id = "quest:4737:title", html = false,
      ja = "Menara Voidrenderを捜して",
      out = "メナラ・ヴォイドレンダーを捜して" },
    { id = "quest:4805:progress", html = false,
      ja = "Winterspringでは、ice thistle yetiっていう大きな生き物と戦うことになる。こいつらは動きはのろいが、分厚い毛皮に守られて多くの攻撃をかわせるんだ。攻撃をかわす力を手に入れたいなら、そいつらから見つけたE'koを持ってきな。\n\n覚えておけ、E'koを狩りたいなら、Cache of Mau'ariを持ち物に入れておかなきゃならねえぞ。",
      out = "ウィンタースプリングでは、アイス・シスル・イェティっていう大きな生き物と戦うことになる。こいつらは動きはのろいが、分厚い毛皮に守られて多くの攻撃をかわせるんだ。攻撃をかわす力を手に入れたいなら、そいつらから見つけたエコを持ってきな。\n\n覚えておけ、エコを狩りたいなら、キャッシュ・オブ・マウアリを持ち物に入れておかなきゃならねえぞ。" },
    { id = "quest:490:progress", html = false,
      ja = "堕落が大地を汚している限り、Teldrassilは栄えることができない。Gnarlpineをこの森から追い払ってくれ、今度こそ永遠に。",
      out = "堕落が大地を汚している限り、テルドラシルは栄えることができない。ナールパインをこの森から追い払ってくれ、今度こそ永遠に。" },
    { id = "quest:5022:progress", html = false,
      ja = "Stormwind国勢調査局へようこそ。住民に関する情報が必要でしたら、お手伝いいたします。",
      out = "ストームウィンド国勢調査局へようこそ。住民に関する情報が必要でしたら、お手伝いいたします。" },
    { id = "quest:5089:title", html = false,
      ja = "General Drakkisath's Command",
      out = "ジェネラル・ドラッキサスズ・コマンド" },
    { id = "quest:5153:completion", html = false,
      ja = "これは何ですか？ wedding ring？ 見せてください……\n\nああ！ このringはかつて偉大な男の手にありました。でも、その男の過去には大きな悲劇があるのです。\n\n彼を助けるために来たのですか？ 今の彼にはもう手遅れです……でも、過去の彼なら助けられるかもしれません！",
      out = "これは何ですか？ ウェディング・リング？ 見せてください……\n\nああ！ このリングはかつて偉大な男の手にありました。でも、その男の過去には大きな悲劇があるのです。\n\n彼を助けるために来たのですか？ 今の彼にはもう手遅れです……でも、過去の彼なら助けられるかもしれません！" },
    { id = "quest:521:title", html = false,
      ja = "Crown of Will",
      out = "クラウン・オブ・ウィル" },
    { id = "quest:5264:title", html = false,
      ja = "Lord Maxwell Tyrosus",
      out = "ロード・マクスウェル・ティロサス" },
    { id = "quest:5405:completion", html = false,
      ja = "Argent Dawnのために悪と戦う者は皆、我らの任命の証を身につけねばならない。それを身につけていれば、我らの補給係が提供する報酬を受け取る権利が得られる。\n\n任命を受けている間は、倒したScourgeからScourgestoneを手に入れられるようになる。これは奴らが時折持っている徽章だ。この徽章を集めて私のもとへ持ってくるのだ。一揃い納めるごとに、我らの英雄の証、Argent Dawn Valor Tokenを受け取れる。\n\n運命を掴め、{class}。今日こそ戦いに加わるのだ！",
      out = "アージェント・ドーンのために悪と戦う者は皆、我らの任命の証を身につけねばならない。それを身につけていれば、我らの補給係が提供する報酬を受け取る権利が得られる。\n\n任命を受けている間は、倒したスコージからスコージストーンを手に入れられるようになる。これは奴らが時折持っている徽章だ。この徽章を集めて私のもとへ持ってくるのだ。一揃い納めるごとに、我らの英雄の証、アージェント・ドーン・ヴァラー・トークンを受け取れる。\n\n運命を掴め、{class}。今日こそ戦いに加わるのだ！" },
    { id = "quest:5517:completion", html = false,
      ja = "実に見事だ、{name}。Chromatic Mantle of the Dawnは今や君のものだ!\n\nArgent DawnとのExaltedの評価を保っている限り、追加のChromatic Mantlesを購入できる。Dawnのどの補給係からでも、すぐに手に入れられるようになる。",
      out = "実に見事だ、{name}。クロマティック・マントル・オブ・ザ・ドーンは今や君のものだ!\n\nアージェント・ドーンとのイグザルテッドの評価を保っている限り、追加のクロマティック・マントルを購入できる。ドーンのどの補給係からでも、すぐに手に入れられるようになる。" },
    { id = "quest:55:progress", html = false,
      ja = "Morbent Felは倒したのか？！",
      out = "モーベント・フェルは倒したのか？！" },
    { id = "quest:5661:description", html = false,
      ja = "Bloodhoof Villageのこんなところまで来るなんて、お前、故郷から遠く離れてるな、{name}。俺は自分の部族のプリーストを見つけて、指導者たちと話すよう送り返すためにここへ来たんだが、だからってお前を助けられないわけじゃない。\n\n聞いた話じゃ、お前らの女司祭長の霊が、Forsakenを皆自分のもとへ呼び寄せたがってるそうだ――お前には学ぶべきことがあるんだ。\n\nお前らの都のWar QuarterにいるAelthalysteに会いに行け。",
      out = "ブラッドフーフ・ヴィレッジのこんなところまで来るなんて、お前、故郷から遠く離れてるな、{name}。俺は自分の部族のプリーストを見つけて、指導者たちと話すよう送り返すためにここへ来たんだが、だからってお前を助けられないわけじゃない。\n\n聞いた話じゃ、お前らの女司祭長の霊が、フォーセイクンを皆自分のもとへ呼び寄せたがってるそうだ――お前には学ぶべきことがあるんだ。\n\nお前らの都のウォー・クオーターにいるエルサリストに会いに行け。" },
    { id = "quest:579:title", html = false,
      ja = "Stormwind図書館",
      out = "ストームウィンド図書館" },
    { id = "quest:5892:progress", html = false,
      ja = "suppliesは持ってきたか、{name}? いくらあっても足りないんだ!",
      out = "サプライは持ってきたか、{name}? いくらあっても足りないんだ!" },
    { id = "quest:600:description", html = false,
      ja = "Venture CompanyはStranglethornのあちこちで事業をやっていて、おかげで俺みたいな働き者のゴブリンが真っ当に金を稼げないんだ！ 頼む、助けてくれ！\n\nVenture Companyは北のCrystalvein Mineの近くで採掘している。basiliskがうじゃうじゃいるから鉱山には入れないが、周りの丘からSinging Crystalsを掘り出すことはできるんだ。\n\n奴らからクリスタルを奪って、ジャングルは奴らの好き勝手にはならないってことを思い知らせてやれ。\n\nそれから……えっと……証拠としてそのクリスタルを俺のところへ持ってきてくれ！",
      out = "ベンチャー・カンパニーはストラングルソーンのあちこちで事業をやっていて、おかげで俺みたいな働き者のゴブリンが真っ当に金を稼げないんだ！ 頼む、助けてくれ！\n\nベンチャー・カンパニーは北のクリスタルヴェイン・マインの近くで採掘している。バジリスクがうじゃうじゃいるから鉱山には入れないが、周りの丘からシンギング・クリスタルを掘り出すことはできるんだ。\n\n奴らからクリスタルを奪って、ジャングルは奴らの好き勝手にはならないってことを思い知らせてやれ。\n\nそれから……えっと……証拠としてそのクリスタルを俺のところへ持ってきてくれ！" },
    { id = "quest:6087:completion", html = false,
      ja = "よし……Earthmotherは君が次の訓練にとりかかれると思し召しだ。",
      out = "よし……アースマザーは君が次の訓練にとりかかれると思し召しだ。" },
    { id = "quest:617:completion", html = false,
      ja = "よくやったな、{name}。akiris reedを10本なんて、結局そんなに難しくなかっただろ? nagaには悪いけどさ、まあ、誰だって食っていかなきゃならないからな。",
      out = "よくやったな、{name}。アキリス・リードを10本なんて、結局そんなに難しくなかっただろ? ナーガには悪いけどさ、まあ、誰だって食っていかなきゃならないからな。" },
    { id = "quest:6341:completion", html = false,
      ja = "ああ、これをAuberdineへ届けたいのですね？わかりました……",
      out = "ああ、これをオーベルダインへ届けたいのですね？わかりました……" },
    { id = "quest:6421:description", html = false,
      ja = "ここStonetalonで何かがおかしいのです。あなたは大気の緊張を感じられますか？　{name}。\n\nここから南東にBoulderslide Ravineという深い洞窟があります。そこのKoboldsは懸命にResoniteとよばれる珍しい結晶を採掘しています。その洞窟でなにが起きているか理解するために、いくらかの鉱石が必要です。また洞窟の深さも調査して下さい。\n\n行ってください、若き{class}。この山の下にどんな悪が潜んでいるかを一刻もはやく突き止めねば。",
      out = "ここストーンタロンで何かがおかしいのです。あなたは大気の緊張を感じられますか？　{name}。\n\nここから南東にボルダースライド・ラヴィーンという深い洞窟があります。そこのコボルドは懸命にレゾナイトとよばれる珍しい結晶を採掘しています。その洞窟でなにが起きているか理解するために、いくらかの鉱石が必要です。また洞窟の深さも調査して下さい。\n\n行ってください、若き{class}。この山の下にどんな悪が潜んでいるかを一刻もはやく突き止めねば。" },
    { id = "quest:65597:objectives", html = false,
      ja = "Lovers' Heartsを使ってincubusを召喚して服従させ、Lovers' HeartsをUndercityのMagic QuarterにいるCarendin Halgarのところへ返して下さい。",
      out = "ラバー・ハートを使ってインキュバスを召喚して服従させ、ラバー・ハートをアンダーシティのマジック・クオーターにいるカレンディン・ハルガーのところへ返して下さい。" },
    { id = "quest:6623:title", html = false,
      ja = "Horde Trauma",
      out = "ホード・トラウマ" },
    { id = "quest:6822:title", html = false,
      ja = "Molten Core",
      out = "モルテン・コア" },
    { id = "quest:69:objectives", html = false,
      ja = "Lion's Pride Innへ行き、Stalvanという名前を聞いたことがある者がいないか確かめて下さい。",
      out = "ライオンズ・プライド・インへ行き、スタルヴァンという名前を聞いたことがある者がいないか確かめて下さい。" },
    { id = "quest:709:objectives", html = false,
      ja = "Tablet of Ryun'ehをTheldurin the Lostに渡して下さい。",
      out = "タブレット・オブ・リューネをセルドゥリン・ザ・ロストに渡して下さい。" },
    { id = "quest:727:description", html = false,
      ja = "Tabletは多くを語る。だが十分ではない！ まったく足りん！\n\n本があるのだ。Yagyinが遠い昔に書いた要約書が。私が逃げてきた……者たちは……その本をあちこちに置いている。そして奴らの最も博識な者たちがそれを研究しているのだ。そこには膨大な知識がある。我らを守るための知識が！\n\nGerrig Bonegripのところへ行け。奴はIronforgeの、Forlorn Cavernにある店にいる。このsigilを見せれば、奴はお前を仲間だと思うだろう。Yagyin's Digestを頼んで……私のところへ持ってくるのだ！",
      out = "タブレットは多くを語る。だが十分ではない！ まったく足りん！\n\n本があるのだ。ヤギンが遠い昔に書いた要約書が。私が逃げてきた……者たちは……その本をあちこちに置いている。そして奴らの最も博識な者たちがそれを研究しているのだ。そこには膨大な知識がある。我らを守るための知識が！\n\nゲリッグ・ボーングリップのところへ行け。奴はアイアンフォージの、フォーローン・ケイヴァーンにある店にいる。このシジルを見せれば、奴はお前を仲間だと思うだろう。ヤギンズ・ダイジェストを頼んで……私のところへ持ってくるのだ！" },
    { id = "quest:7486:description", html = false,
      ja = "{name}、Warlordsへのそなたの奉仕は、この世界の住人に我らが期待し得るすべてを超えていた。\n\n我らには、そなたらの民の感謝や善行への報いという考えが分からぬ。だが、この場合は……報いが与えられてしかるべきかもしれぬ。\n\nこの島の南の麓、波の下に、宝箱がある。その中に、そなたの……報酬がある。\n\n行け、{name}。報酬を受け取るがよい。",
      out = "{name}、ウォーロードへのそなたの奉仕は、この世界の住人に我らが期待し得るすべてを超えていた。\n\n我らには、そなたらの民の感謝や善行への報いという考えが分からぬ。だが、この場合は……報いが与えられてしかるべきかもしれぬ。\n\nこの島の南の麓、波の下に、宝箱がある。その中に、そなたの……報酬がある。\n\n行け、{name}。報酬を受け取るがよい。" },
    { id = "quest:75:description", html = false,
      ja = "この家に越してきたとき、二階の箱に羊皮紙の束が入っていた。来たばかりの頃に一度見たんだが、目がかすんできて諦めてしまったよ。\n\n目がほとんど見えない老いぼれの頼みを聞いて、このStalvanという人物についてもっと知るクエストに役立ちそうなものがないか、二階の箱を調べてくれないか。たしか、あんたの興味を引きそうな色あせた日記のページがあったはずだ。それを持ってきてくれれば、できる限りのことをして手伝うよ。",
      out = "この家に越してきたとき、二階の箱に羊皮紙の束が入っていた。来たばかりの頃に一度見たんだが、目がかすんできて諦めてしまったよ。\n\n目がほとんど見えない老いぼれの頼みを聞いて、このスタルヴァンという人物についてもっと知るクエストに役立ちそうなものがないか、二階の箱を調べてくれないか。たしか、あんたの興味を引きそうな色あせた日記のページがあったはずだ。それを持ってきてくれれば、できる限りのことをして手伝うよ。" },
    { id = "quest:7647:objectives", html = false,
      ja = "ScholomanceにあるGreat Ossuaryの地下の中心でDivination Scryerを使う。そうすれば、あなたが裁かなければならない霊たちが現れる。その霊たちを倒すとDeath Knight Darkreaverが呼び出される。彼を倒し、倒れた軍馬の失われた魂を取り戻す。\n\nCharger's Redeemed SoulとBlessed Enchanted BardingをDarkreaver's Fallen Chargerに渡して下さい。",
      out = "スカラマンスにあるグレート・オシュアリーの地下の中心でディビネーション・スクライヤーを使う。そうすれば、あなたが裁かなければならない霊たちが現れる。その霊たちを倒すとデス・ナイト・ダークリーヴァーが呼び出される。彼を倒し、倒れた軍馬の失われた魂を取り戻す。\n\nチャージャーズ・リディームド・ソウルとブレスト・エンチャンテッド・バーディングをダークリーヴァーズ・フォールン・チャージャーに渡して下さい。" },
    { id = "quest:773:completion", html = false,
      ja = "Earthmotherの儀式に通るため、そなたは不断の努力を示してくれた、{name}。\n\n我々祖霊は、我らの偉大なる都Thunder Bluffを守り礎を築くために勇敢な命を捧げた、大いなるトーレンの者たちの象徴なのだ。\n\n私はこれをもって、その守護の務めをそなたに託す。\n\nそなたは知恵の儀式を無事に終えたのだ、若き{class}。誇りをもってThunder Bluffへ入るがよい。",
      out = "アースマザーの儀式に通るため、そなたは不断の努力を示してくれた、{name}。\n\n我々祖霊は、我らの偉大なる都サンダー・ブラフを守り礎を築くために勇敢な命を捧げた、大いなるトーレンの者たちの象徴なのだ。\n\n私はこれをもって、その守護の務めをそなたに託す。\n\nそなたは知恵の儀式を無事に終えたのだ、若き{class}。誇りをもってサンダー・ブラフへ入るがよい。" },
    { id = "quest:7815:title", html = false,
      ja = "Snapjawsだぜ、兄弟！",
      out = "スナップジョーだぜ、兄弟！" },
    { id = "quest:78676:description", html = false,
      ja = "<箱の中にメモが入っている>\n\nまた会えて嬉しいよ、{name}。\n\n私が今欲しているのは、Eye of Bhosscaと呼ばれる遺物だ。情報筋によれば、その目はScarlet Monasteryのどこかにあるらしい。Shadowfang Keepのときと同じく、修道院には一人で潜入してもらう。\n\n入る前に変装を見つけておくといいだろう。動き回るのが少し楽になる。修道院の敷地で何か見つかるはずだ。\n\nその目をここへ持ち帰れば、前回と同じように報酬を届けよう。\n\n- C",
      out = "<箱の中にメモが入っている>\n\nまた会えて嬉しいよ、{name}。\n\n私が今欲しているのは、アイ・オブ・ボスカと呼ばれる遺物だ。情報筋によれば、その目はスカーレット・モナステリーのどこかにあるらしい。シャドウファング・キープのときと同じく、修道院には一人で潜入してもらう。\n\n入る前に変装を見つけておくといいだろう。動き回るのが少し楽になる。修道院の敷地で何か見つかるはずだ。\n\nその目をここへ持ち帰れば、前回と同じように報酬を届けよう。\n\n- シー" },
    { id = "quest:79236:description", html = false,
      ja = "元帥の仲間か？いや、そうは見えないな。\n\nお前が聞いた噂は半分しか本当じゃない。確かに俺たちは人間とドワーフの野営地を荒らしていたが、Hordeのためにやっていたわけじゃない。個人的に雇われていたんだ。\n\ngrogをおごってくれたら、全部話してやるよ。",
      out = "元帥の仲間か？いや、そうは見えないな。\n\nお前が聞いた噂は半分しか本当じゃない。確かに俺たちは人間とドワーフの野営地を荒らしていたが、ホードのためにやっていたわけじゃない。個人的に雇われていたんだ。\n\nグロッグをおごってくれたら、全部話してやるよ。" },
    { id = "quest:80411:description", html = false,
      ja = "我々が傍受した最新の手紙によれば、Caiusが求める最後の遺物はTalisman of Kazdorのようだ。手紙によると、このTalismanはZul'Farrakのどこかにあるらしい。\n\n疑いを招かないよう、Caiusの指示どおりに仕事をこなしてもらいたい。つまり、いつも通り一人でZul'Farrakに入ってもらうことになる。\n\nただし、Talismanを渡す前に、ここへ持ってきてくれ。Caiusには、頼んだもの以上のものをくれてやろう。",
      out = "我々が傍受した最新の手紙によれば、カイウスが求める最後の遺物はタリスマン・オブ・カズドールのようだ。手紙によると、このタリスマンはズル・ファラックのどこかにあるらしい。\n\n疑いを招かないよう、カイウスの指示どおりに仕事をこなしてもらいたい。つまり、いつも通り一人でズル・ファラックに入ってもらうことになる。\n\nただし、タリスマンを渡す前に、ここへ持ってきてくれ。カイウスには、頼んだもの以上のものをくれてやろう。" },
    { id = "quest:8072:objectives", html = false,
      ja = "Primal Hakkari GirdleをFalthir the Sightlessのところへ持って行って下さい。また、Zandalar Tribeとの評判がHonored以上である必要があります。\n\nFalthir the SightlessはStranglethorn ValeのYojamba Isleにいます。",
      out = "プライマル・ハッカリ・ガードルをファルシア・ザ・サイトレスのところへ持って行って下さい。また、ザンダラー・トライブとの評判がオナード以上である必要があります。\n\nファルシア・ザ・サイトレスはストラングルソーン・ヴェイルのヨジャンバ・アイルにいます。" },
    { id = "quest:8148:progress", html = false,
      ja = "MolthorがKing Rastakhanからの言葉を届けてくれた、{name}。宮廷はお前によるHakkariの軍勢の殲滅にいたく感銘を受けている。お前のタリスマンに最後の織り目を授けるよう命じられた。私に渡すがよい。",
      out = "モルソーがキング・ラスタカーンからの言葉を届けてくれた、{name}。宮廷はお前によるハッカリの軍勢の殲滅にいたく感銘を受けている。お前のタリスマンに最後の織り目を授けるよう命じられた。私に渡すがよい。" },
    { id = "quest:81766:objectives", html = false,
      ja = "書状をStormwindのCathedral of LightにいるKatherine the Pureのところへ持って行ってください。",
      out = "書状をストームウィンドのカテドラル・オブ・ライトにいるキャサリン・ザ・ピュアのところへ持って行ってください。" },
    { id = "quest:81859:title", html = false,
      ja = "Feralas任務V：Cenarionの情報",
      out = "フェララス任務ブイ：セナリウスの情報" },
    { id = "quest:8250:description", html = false,
      ja = "Archmage Xylemが最近あちこちで尋ねて回っている……あなたほどの経験を持つ者をね。\n\n彼を訪ねたいなら、Azsharaで見つけられる。彼の塔は崖の上高くに建てられていて、上へ行く唯一の方法は、彼の傲慢な従者Sanath Lim-yoが唱えるテレポートの呪文だ。\n\nSanathは主人の塔の下に野営している。彼を見つけるには、Azsharaの大通りがRuins of Eldarathの入口で分かれるところまで行くといい。その場所からまっすぐ北へ進めば、崖にたどり着くだろう。",
      out = "アークメイジ・ザイレムが最近あちこちで尋ねて回っている……あなたほどの経験を持つ者をね。\n\n彼を訪ねたいなら、アズシャラで見つけられる。彼の塔は崖の上高くに建てられていて、上へ行く唯一の方法は、彼の傲慢な従者サナス・リム・ヨーが唱えるテレポートの呪文だ。\n\nサナスは主人の塔の下に野営している。彼を見つけるには、アズシャラの大通りがルイン・オブ・エルダラスの入口で分かれるところまで行くといい。その場所からまっすぐ北へ進めば、崖にたどり着くだろう。" },
    { id = "quest:8294:description", html = false,
      ja = "Ashenvaleの森の荒野は、Hordeの力に屈するのだ、{race}。Silverwingが何を言おうと何をしようと、我らの至上の使命を止めることはできん。KalimdorはHordeのものだ。当然我らのものであるものを刈り取るのを、奴らはよくも邪魔しようとするものだ！\n\n奴らが我らの前進を遅らせようとするひ弱な試みを切り崩しながら、胸に誇りをみなぎらせるがいい。Silverwing Sentinelsを倒し、Warsong mark of honorを手に入れろ。その印を持って戻ってくれば、{name}、報酬を与えよう。",
      out = "アッシェンヴェイルの森の荒野は、ホードの力に屈するのだ、{race}。シルバーウィングが何を言おうと何をしようと、我らの至上の使命を止めることはできん。カリムドアはホードのものだ。当然我らのものであるものを刈り取るのを、奴らはよくも邪魔しようとするものだ！\n\n奴らが我らの前進を遅らせようとするひ弱な試みを切り崩しながら、胸に誇りをみなぎらせるがいい。シルバーウィング・センチネルを倒し、ウォーソング・マーク・オブ・オナーを手に入れろ。その印を持って戻ってくれば、{name}、報酬を与えよう。" },
    { id = "quest:8355:description", html = false,
      ja = "お菓子ねだりだな! 頑張れよ!ところで、あんたは病気の子のためにキャンディーを集めて何やら慈善活動のようなことをしているようだが、俺はそう甘く見てはやらんぞ。その子にあげる美味しいGnomeregan Gumdropがあるが……汽車の汽笛をやってみせてくれるならな! ははは、そう、おふざけだよ! このガムドロップの代金は汽笛一回さ!シュッポ、シュッポ、{class}!",
      out = "お菓子ねだりだな! 頑張れよ!ところで、あんたは病気の子のためにキャンディーを集めて何やら慈善活動のようなことをしているようだが、俺はそう甘く見てはやらんぞ。その子にあげる美味しいノームリガン・ガムドロップがあるが……汽車の汽笛をやってみせてくれるならな! ははは、そう、おふざけだよ! このガムドロップの代金は汽笛一回さ!シュッポ、シュッポ、{class}!" },
    { id = "quest:8401:objectives", html = false,
      ja = "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。",
      out = "ウォーソング・ガルチ・マーク・オブ・オナーを$N1個、戦場の外にいるアライアンス・ブリガディア・ジェネラルのところへ持って行って下さい。" },
    { id = "quest:8428:completion", html = false,
      ja = "素晴らしい! Warsong Gulchでの我々の作戦を守り、その価値を示してくれた! 君の名誉の噂が我らの地の隅々にまで広まらんことを。",
      out = "素晴らしい! ウォーソング・ガルチでの我々の作戦を守り、その価値を示してくれた! 君の名誉の噂が我らの地の隅々にまで広まらんことを。" },
    { id = "quest:8470:title", html = false,
      ja = "Deadwood Ritual Totem",
      out = "デッドウッド・リチュアル・トーテム" },
    { id = "quest:8549:completion", html = false,
      ja = "こうして私たちの努力によって、戦いへとまた一歩近づくのです。このpeacebloomを懸命に集めてくれてありがとう、{class}。必ず役立てると約束しますし、あなたの貢献は心に留めておきますよ、{name}。その気があれば、どうかまたこの花を持って私のもとへ戻ってきてください。それまで、Earth Motherがあなたを導きますように。",
      out = "こうして私たちの努力によって、戦いへとまた一歩近づくのです。このピースブルームを懸命に集めてくれてありがとう、{class}。必ず役立てると約束しますし、あなたの貢献は心に留めておきますよ、{name}。その気があれば、どうかまたこの花を持って私のもとへ戻ってきてください。それまで、アース・マザーがあなたを導きますように。" },
    { id = "quest:860:title", html = false,
      ja = "Sergra Darkthorn",
      out = "セルグラ・ダークソーン" },
    { id = "quest:867:title", html = false,
      ja = "Harpy襲撃者",
      out = "ハーピー襲撃者" },
    { id = "quest:8728:description", html = false,
      ja = "いやはや、思ったより少し時間がかかったね。さて、この台帳に何が書いてあるか見てみよう。\n\n<Narainは時折小声でぶつぶつ言いながら、黙って台帳を読んでいる。>\n\n良い知らせは、君の仕様どおりに機能するarcaniteのブイを作れると99%確信しているということだ。もちろん、それは悪い知らせ次第なんだがね。\n\n悪い知らせは、大量のarcaniteとelementium ore、それに珍しい宝石が必要になるということだ。\n\n必要なものを持ってきてくれれば、ブイを作ってあげよう。",
      out = "いやはや、思ったより少し時間がかかったね。さて、この台帳に何が書いてあるか見てみよう。\n\n<ナレインは時折小声でぶつぶつ言いながら、黙って台帳を読んでいる。>\n\n良い知らせは、君の仕様どおりに機能するアーケイナイトのブイを作れると99%確信しているということだ。もちろん、それは悪い知らせ次第なんだがね。\n\n悪い知らせは、大量のアーケイナイトとエレメンティウム・オア、それに珍しい宝石が必要になるということだ。\n\n必要なものを持ってきてくれれば、ブイを作ってあげよう。" },
    { id = "quest:8796:description", html = false,
      ja = "やあ、話を聞いてくれる気になってくれて嬉しいよ。AllianceはAhn'Qiraj Warの準備のために、得られる限りの助けを必要としているんだ。つまり、君が必要なのさ！ こうして話している今も、公式の収集係が来たる戦争に必要な物資を集めているんだが、君の助けなしじゃ目標を達成できないんだ、{name}！\n\n責任者のField Marshal Snowfallと話してくるといい。どうだい、{class}？ この重要な準備を手伝ってくれるかい？",
      out = "やあ、話を聞いてくれる気になってくれて嬉しいよ。アライアンスはアンキラージ・ウォーの準備のために、得られる限りの助けを必要としているんだ。つまり、君が必要なのさ！ こうして話している今も、公式の収集係が来たる戦争に必要な物資を集めているんだが、君の助けなしじゃ目標を達成できないんだ、{name}！\n\n責任者のフィールド・マーシャル・スノーフォールと話してくるといい。どうだい、{class}？ この重要な準備を手伝ってくれるかい？" },
    { id = "quest:8859:objectives", html = false,
      ja = "Colossus of Zora's HuskをEastern PlaguelandsのLight's Hope ChapelにいるLord Maxwell Tyrosusのところへ持って行って下さい。",
      out = "コロッサス・オブ・ゾーラズ・ハスクをイースタン・プレイグランドのライツ・ホープ・チャペルにいるロード・マクスウェル・ティロサスのところへ持って行って下さい。" },
    { id = "quest:8909:objectives", html = false,
      ja = "Winterspring Blood Samplesを$N1個と$N2ゴールドを手に入れ、Devout Bracersを$N3組と一緒にIronforgeのDelianaのところへ持って行って下さい。",
      out = "ウィンタースプリング・ブラッド・サンプルを$N1個と$N2ゴールドを手に入れ、ディバウト・ブレイサーを$N3組と一緒にアイアンフォージのデリアナのところへ持って行って下さい。" },
    { id = "quest:8955:completion", html = false,
      ja = "私たちの命がこの馬鹿げたメダルのせいですっかり犠牲になっているだなんて、信じられないわ! それで、AnthionがBodleyについて話したことは確かなの?\n\nじゃ、あなたは仕事を終えたのだから、忘れないうちに報酬を渡しましょう。",
      out = "私たちの命がこの馬鹿げたメダルのせいですっかり犠牲になっているだなんて、信じられないわ! それで、アンシオンがボドリーについて話したことは確かなの?\n\nじゃ、あなたは仕事を終えたのだから、忘れないうちに報酬を渡しましょう。" },
    { id = "quest:8999:objectives", html = false,
      ja = "Wildheart CowlとWildheart VestをDelianaに渡して下さい。",
      out = "ワイルドハート・カウルとワイルドハート・ベストをデリアナに渡して下さい。" },
    { id = "quest:906:completion", html = false,
      ja = "{name}、Razormaneの指導者を見つけて殺したのか?　信じられん。\n\n何も言えない、が、感謝していないということではないぞ。Crossroadsの者たちは君の力に心から敬意を払うだろう。\n\n過ちは認めねばならんな。補給路を襲撃している指導者を別のquilboarだと思っていたのだ。もう一度礼を言うぞ、{name}。",
      out = "{name}、レイザーメインの指導者を見つけて殺したのか?　信じられん。\n\n何も言えない、が、感謝していないということではないぞ。クロスロードの者たちは君の力に心から敬意を払うだろう。\n\n過ちは認めねばならんな。補給路を襲撃している指導者を別のキルボアだと思っていたのだ。もう一度礼を言うぞ、{name}。" },
    { id = "quest:915:completion", html = false,
      ja = "んんーっ! ここのイチゴのアイスクリーム大好き! TiguleとFororに得意なことが一つあるとしたら、それはアイスクリーム作りだね!\n\n本当にありがとう{name}――こんなに素敵なおやつは初めてだよ!",
      out = "んんーっ! ここのイチゴのアイスクリーム大好き! ティグルとフォラーに得意なことが一つあるとしたら、それはアイスクリーム作りだね!\n\n本当にありがとう{name}――こんなに素敵なおやつは初めてだよ!" },
    { id = "quest:91920:completion", html = false,
      ja = "薬が効かなかった？当然だ、効くはずがない。お前が持ってきた心臓は足りなかった。レシピにははっきり6個と書いてある。お前が持ってきたのは3個だ。\n\nもっとも、murlocの部位の使い道は今まで考えたこともなかったが……\n\n<Renferrelは目玉を受け取る。>\n\nお前のDeathstalkerの力を取り戻すためなら、私の手持ちの心臓を少しくらい犠牲にしても構わん。",
      out = "薬が効かなかった？当然だ、効くはずがない。お前が持ってきた心臓は足りなかった。レシピにははっきり6個と書いてある。お前が持ってきたのは3個だ。\n\nもっとも、マーロックの部位の使い道は今まで考えたこともなかったが……\n\n<レンフェレルは目玉を受け取る。>\n\nお前のデスストーカーの力を取り戻すためなら、私の手持ちの心臓を少しくらい犠牲にしても構わん。" },
    { id = "quest:9239:description", html = false,
      ja = "あんたとOmarionに感謝するよ。Omarionが安らかに眠れますように。これでGlacial glovesを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。",
      out = "あんたとオマリオンに感謝するよ。オマリオンが安らかに眠れますように。これでグレイシャル・グローブを作ることができるぞ。あんたにしてもらわなきゃならんのは、材料を持ってくることと、ちょっとした製作費の支払いだ。" },
    { id = "quest:924:completion", html = false,
      ja = "任務完了だね。Neeruの望みどおりDemon Seedは破壊されたようだ。しかしこれで終わりではないよ・・。\n\nDemon Seedの破壊はエーテルを通して驚くほど強力な波動を送った。私も感じたよ。ほかにも気づいたものがいるだろう。自分たちのおもちゃがなぜ壊れたのか不思議に思うものもいるだろうね・・・。\n\nまあそれはさておき、渡すものがある。Neeruからだ。感謝してると伝えてくれともね。\n\nまあ、ありがとう。",
      out = "任務完了だね。ニーエルの望みどおりデーモン・シードは破壊されたようだ。しかしこれで終わりではないよ・・。\n\nデーモン・シードの破壊はエーテルを通して驚くほど強力な波動を送った。私も感じたよ。ほかにも気づいたものがいるだろう。自分たちのおもちゃがなぜ壊れたのか不思議に思うものもいるだろうね・・・。\n\nまあそれはさておき、渡すものがある。ニーエルからだ。感謝してると伝えてくれともね。\n\nまあ、ありがとう。" },
    { id = "quest:92683:title", html = false,
      ja = "Flutterfly Dust",
      out = "フラッターフライ・ダスト" },
    { id = "quest:92860:objectives", html = false,
      ja = "Valennia Stormfistに報告し、Al'Akethとの戦いでHigh Orderが彼らと共にあることを伝えて下さい。",
      out = "ヴァレニア・ストームフィストに報告し、アルアケスとの戦いでハイ・オーダーが彼らと共にあることを伝えて下さい。" },
    { id = "quest:93173:description", html = false,
      ja = "<Wind Hollowをひとつにまとめていた渦巻く気流が消え始めると、小さな金属の装置があなたの足元の地面に転がり落ちた。何かの機械仕掛けの道具のようだ。The Strange Hermitは、まだいくつかの装備が見つからないと言っていた。彼ならこれに興味を持つかもしれない。>",
      out = "<ウィンド・ホロウをひとつにまとめていた渦巻く気流が消え始めると、小さな金属の装置があなたの足元の地面に転がり落ちた。何かの機械仕掛けの道具のようだ。ストレンジ・ハーミットは、まだいくつかの装備が見つからないと言っていた。彼ならこれに興味を持つかもしれない。>" },
    { id = "quest:93551:objectives", html = false,
      ja = "Embroidered Scabbardを使い、Mount HyjalのMourning's Restにある壊れた大砲の近くでVeteran of the Third Warと会ってください。",
      out = "エンブロイダード・スキャバードを使い、マウント・ハイジャルのモーニングズ・レストにある壊れた大砲の近くでベテラン・オブ・ザ・サード・ウォーと会ってください。" },
    { id = "quest:93835:description", html = false,
      ja = "Lorthunaは何かのポータルを使って上の尖塔へ逃げた。AyessaとElaadrinが後を追って入っていった。ほんの少し前のことだ。\n\nすまないが、攻撃を1発多く食らいすぎた。私はここまでだ。ポータルを抜けて、Elaadrinを見つけ、彼らがLorthunaを止めるのを手伝ってくれ。\n\nElaadrinとAyessaが呼んだという援軍がすぐに来ない限り、ここからは君一人だ。幸運を、{class}。",
      out = "ロースナは何かのポータルを使って上の尖塔へ逃げた。アイエッサとエラードリンが後を追って入っていった。ほんの少し前のことだ。\n\nすまないが、攻撃を1発多く食らいすぎた。私はここまでだ。ポータルを抜けて、エラードリンを見つけ、彼らがロースナを止めるのを手伝ってくれ。\n\nエラードリンとアイエッサが呼んだという援軍がすぐに来ない限り、ここからは君一人だ。幸運を、{class}。" },
    { id = "quest:94237:title", html = false,
      ja = "Craftsman's Writ: Crafted Solid Shot",
      out = "クラフツマンズ・リット: クラフテッド・ソリッド・ショット" },
    { id = "quest:94306:title", html = false,
      ja = "Craftsman's Writ: Crimson Silk Robe",
      out = "クラフツマンズ・リット: クリムゾン・シルク・ローブ" },
    { id = "quest:94435:objectives", html = false,
      ja = "Bandarion KeepのDanitha Morrのところへ戻ってください。",
      out = "バンダリオン・キープのダニサ・モアのところへ戻ってください。" },
    { id = "quest:94733:objectives", html = false,
      ja = "Bolder'okでGobamを見つける。",
      out = "ボルダーオックでゴバムを見つける。" },
    { id = "quest:94913:completion", html = false,
      ja = "ほう、もうBearの姿を会得したようだな。よし、よし。順調に進んでいるぞ、若き{class}。",
      out = "ほう、もうベアの姿を会得したようだな。よし、よし。順調に進んでいるぞ、若き{class}。" },
    { id = "quest:95121:objectives", html = false,
      ja = "Fimbo Greasemitzのために、Murloc Eyeを12個とSand Crawler Meatを6個集める。",
      out = "フィンボ・グリースミッツのために、マーロック・アイを12個とサンド・クローラー・ミートを6個集める。" },
    { id = "quest:95312:objectives", html = false,
      ja = "GadgetzanにいるFizbuz Mithrilと話す。",
      out = "ガジェッツァンにいるフィズバズ・ミスリルと話す。" },
    { id = "quest:95646:objectives", html = false,
      ja = "Excavation Sitesの中でHighland Horrorを倒し、その根の核をWetlandsのRethiel the Greenwardenのところへ持って行って下さい。",
      out = "エクスカベーション・サイトの中でハイランド・ホラーを倒し、その根の核をウェットランドのレシエル・ザ・グリーンウォーデンのところへ持って行って下さい。" },
    { id = "quest:95981:description", html = false,
      ja = "奴らのペンダントを奪うのは最初の一歩にすぎない。もしKirin Torが本当にDalaranから遺物を絶えず送り込んでいるのなら、元から断たねばならん。\n\nAmbermillの周りの道で、Dalaranの魔術師と監視者を探せ。奴らのせいで、あまりにも長いあいだ我らの国境を自由に行き来されてきた。奴らの数を減らせれば、そもそもこのペンダントがSilverpine Forestに入ってくるのを止められるはずだ。",
      out = "奴らのペンダントを奪うのは最初の一歩にすぎない。もしキリン・トーが本当にダラランから遺物を絶えず送り込んでいるのなら、元から断たねばならん。\n\nアンバーミルの周りの道で、ダラランの魔術師と監視者を探せ。奴らのせいで、あまりにも長いあいだ我らの国境を自由に行き来されてきた。奴らの数を減らせれば、そもそもこのペンダントがシルバーパイン・フォレストに入ってくるのを止められるはずだ。" },
    { id = "quest:961:completion", html = false,
      ja = "Twilight's Hammerの教団員が見つかったというのは気がかりです。彼らの意図について瞑想しなければなりません……\n\nさらに情報を得たら、占いの鉢を通して私に話しかけてください。鉢を作るのにphial of scryingが必要なら……もう一つ差し上げましょう。",
      out = "トワイライツ・ハンマーの教団員が見つかったというのは気がかりです。彼らの意図について瞑想しなければなりません……\n\nさらに情報を得たら、占いの鉢を通して私に話しかけてください。鉢を作るのにファイアル・オブ・スクライイングが必要なら……もう一つ差し上げましょう。" },
    { id = "quest:96627:description", html = false,
      ja = "{name}、あなたはこれまで守り手としての力量を示してきた。だからこそ、今ひとつ変わった任務を託したい。\n\nGoldshireの近くの道沿いに、新顔の冒険者がいると聞いた。行って、彼が何をしているのか見てきてくれ。",
      out = "{name}、あなたはこれまで守り手としての力量を示してきた。だからこそ、今ひとつ変わった任務を託したい。\n\nゴールドシャイアの近くの道沿いに、新顔の冒険者がいると聞いた。行って、彼が何をしているのか見てきてくれ。" },
    { id = "quest:96899:title", html = false,
      ja = "Bandarion Keep",
      out = "バンダリオン・キープ" },
    { id = "quest:97184:description", html = false,
      ja = "次に、お前の最後の試練に欠かせないDivination Scryerを組み立てねばならない。お前がTerrordaleで使ったexorcism censerがその触媒となる。占いの装置にふさわしい器は、私が作れるはずだ。\n\nだが、最後に必要な部品は2つのダイヤモンドだ。白を1つ、黒を1つ。これはThe Forsakenのパラディンとしての我らの本質の二面性を表している。この2つが道しるべとなり、scryerが生者と死者を隔てる帳を貫くのだ。",
      out = "次に、お前の最後の試練に欠かせないディビネーション・スクライヤーを組み立てねばならない。お前がテラーデイルで使ったエクソシズム・センサーがその触媒となる。占いの装置にふさわしい器は、私が作れるはずだ。\n\nだが、最後に必要な部品は2つのダイヤモンドだ。白を1つ、黒を1つ。これはフォーセイクンのパラディンとしての我らの本質の二面性を表している。この2つが道しるべとなり、スクライヤーが生者と死者を隔てる帳を貫くのだ。" },
    { id = "quest:97329:description", html = false,
      ja = "あんた！そう、あんただ！こっちに来てくれ、声を落として！\n\n大失敗しちまった。Booty Bayのために、あいつらの飛行船の塔を速達便に使えるうまい取引をまとめたんだが、最初の便で、でっかい鳥を見て……いや、すぐここの東で撃ち落とされたんだ！\n\n墜落からは、あいにく生き延びたんだが、目が覚める前にもう耳を引っ張られて引きずられてたんだ！今じゃ血に飢えたトロールに囲まれて、檻に閉じ込められてる！\n\nいいか、鍵さえあればいいんだ、な？自分で逃げられるから。",
      out = "あんた！そう、あんただ！こっちに来てくれ、声を落として！\n\n大失敗しちまった。ブーティ・ベイのために、あいつらの飛行船の塔を速達便に使えるうまい取引をまとめたんだが、最初の便で、でっかい鳥を見て……いや、すぐここの東で撃ち落とされたんだ！\n\n墜落からは、あいにく生き延びたんだが、目が覚める前にもう耳を引っ張られて引きずられてたんだ！今じゃ血に飢えたトロールに囲まれて、檻に閉じ込められてる！\n\nいいか、鍵さえあればいいんだ、な？自分で逃げられるから。" },
    { id = "quest:97917:completion", html = false,
      ja = "さあ、これで君も自分だけのEnchanted Luteを作れるようになった。町の真ん中に野営地を張られるのを好む者はあまりいないから、試してみたいなら荒野へ出かける必要があるよ。\n\nああ、それと覚えておいてくれ。焚き火のない野営地は完成とは言えない。野営地を始める前に、焚き火がひとつ必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる人のところへ行って、基本を学んでおくといい。",
      out = "さあ、これで君も自分だけのエンチャンテッド・リュートを作れるようになった。町の真ん中に野営地を張られるのを好む者はあまりいないから、試してみたいなら荒野へ出かける必要があるよ。\n\nああ、それと覚えておいてくれ。焚き火のない野営地は完成とは言えない。野営地を始める前に、焚き火がひとつ必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる人のところへ行って、基本を学んでおくといい。" },
    { id = "quest:97961:description", html = false,
      ja = "Tailoringは、打ち込むには意外なほど強力な生産スキルだ。きっとあんたの役に立つよ。\n\n腕が足りていればの話だが、野営地用のFaction Bannerの作り方を教えてくれる奴を知ってるよ。どんな戦場でも、鼓舞と士気は成功の鍵だ。心を奮い立たせる旗があれば、元気を保つのに大いに役立つさ。",
      out = "テイラリングは、打ち込むには意外なほど強力な生産スキルだ。きっとあんたの役に立つよ。\n\n腕が足りていればの話だが、野営地用のファクション・バナーの作り方を教えてくれる奴を知ってるよ。どんな戦場でも、鼓舞と士気は成功の鍵だ。心を奮い立たせる旗があれば、元気を保つのに大いに役立つさ。" },
    { id = "quest:98192:description", html = false,
      ja = "お前、ちっちゃい！お前、Krakが赤いガブガブつぶして鱗の皮とるの手伝う！\n\nKrak、鱗の皮とるため赤いガブガブつぶす。でもKrakの手、でかすぎ。Krak、皮切ってばかり、穴だらけにする。\n\nでもお前、ちっちゃい！お前、南のDragonmurkの赤いガブガブから皮とってこい。あいつら、意地悪で速い。お前ちっちゃい、食われるかも。",
      out = "お前、ちっちゃい！お前、クラクが赤いガブガブつぶして鱗の皮とるの手伝う！\n\nクラク、鱗の皮とるため赤いガブガブつぶす。でもクラクの手、でかすぎ。クラク、皮切ってばかり、穴だらけにする。\n\nでもお前、ちっちゃい！お前、南のドラゴンマークの赤いガブガブから皮とってこい。あいつら、意地悪で速い。お前ちっちゃい、食われるかも。" },
    { id = "quest:98386:objectives", html = false,
      ja = "RedridgeにいるForeman Oslowのために、Alther's MillでGreater Tarantulaを$N1匹倒し、Tarantula Eggを$N2個壊してください。",
      out = "レッドリッジにいるフォアマン・オスローのために、アルサーズ・ミルでグレーター・タランチュラを$N1匹倒し、タランチュラ・エッグを$N2個壊してください。" },
    { id = "quest:98739:title", html = false,
      ja = "Great Cat Spiritの祝福",
      out = "グレート・キャット・スピリットの祝福" },
    { id = "quest:99142:title", html = false,
      ja = "Tomb Weed",
      out = "トゥーム・ウィード" },
    { id = "spell:10161:description", html = false,
      ja = "術者の前方の円錐範囲にいる対象は$N1のFrostダメージを受け、$D1の間、移動速度が$N2%低下します。この円錐で最初に命中した$N4体の対象は、さらに$N5%減速し、その時間が$D2延長されます。",
      out = "術者の前方の円錐範囲にいる対象は$N1のフロストダメージを受け、$D1の間、移動速度が$N2%低下します。この円錐で最初に命中した$N4体の対象は、さらに$N5%減速し、その時間が$D2延長されます。" },
    { id = "spell:10627:description", html = false,
      ja = "術者の足元に体力$N1のGrace of Air Totemを召喚します。トーテムは$N2ヤード以内のパーティまたはレイドメンバーの敏捷性を$N3上昇させます。効果時間は$D1です。",
      out = "術者の足元に体力$N1のグレイス・オブ・エア・トーテムを召喚します。トーテムは$N2ヤード以内のパーティまたはレイドメンバーの敏捷性を$N3上昇させます。効果時間は$D1です。" },
    { id = "spell:11189:description", html = false,
      ja = "Frost ArmorとIce Armorの呪文が与えるアーマーと抵抗力を$N1%上げ、Frost Wardに$N2%の確率で防いだダメージ呪文を無効化する効果を与え、Ice BarrierとFrost Wardの吸収量を$N3%増やします。",
      out = "フロスト・アーマーとアイス・アーマーの呪文が与えるアーマーと抵抗力を$N1%上げ、フロスト・ウォードに$N2%の確率で防いだダメージ呪文を無効化する効果を与え、アイス・バリアとフロスト・ウォードの吸収量を$N3%増やします。" },
    { id = "spell:11713:aura", html = false,
      ja = "$D1かけて$?$w3>0[$N1][$N2]のShadowダメージを受けます。",
      out = "$D1かけて$?$w3>0[$N1][$N2]のシャドウダメージを受けます。" },
    { id = "spell:1213349:description", html = false,
      ja = "Divine Lightのクールダウンを$N1%短縮します。",
      out = "ディバイン・ライトのクールダウンを$N1%短縮します。" },
    { id = "spell:1215511:aura", html = false,
      ja = "$N1のNatureダメージを吸収します。",
      out = "$N1のネイチャーダメージを吸収します。" },
    { id = "spell:1219226:description", html = false,
      ja = "アンデッドの敵からのダメージで体力が$N1%未満になるとき、Hand of ReckoningとRighteous Furyの効果がそのダメージを$N2%減少させるようになります。",
      out = "アンデッドの敵からのダメージで体力が$N1%未満になるとき、ハンド・オブ・レコニングとライチャス・フューリーの効果がそのダメージを$N2%減少させるようになります。" },
    { id = "spell:1219827:description", html = false,
      ja = "肩にSoul of the Faithfulを永続的に宿らせます：\r\n\n詠唱中も、マナ回復の$N1%が継続します。",
      out = "肩にソウル・オブ・ザ・フェイスフルを永続的に宿らせます：\r\n\n詠唱中も、マナ回復の$N1%が継続します。" },
    { id = "spell:1219990:description", html = false,
      ja = "Gladiator Stanceの間、Bloodrageのクールダウンを$D1短縮します。",
      out = "グラディエーター・スタンスの間、ブラッドレイジのクールダウンを$D1短縮します。" },
    { id = "spell:1220310:description", html = false,
      ja = "Swipeが、主な対象にかかっている自分のLacerateを、Swipeが命中した他の対象にも広げるようになります。",
      out = "スワイプが、主な対象にかかっている自分のラセレイトを、スワイプが命中した他の対象にも広げるようになります。" },
    { id = "spell:1223375:aura", html = false,
      ja = "Naxxramasの中にいる間、あなたの潜在能力を解放します。装備しているSanctifiedアイテム一つにつき、生み出す脅威が$N1%、与えるダメージが$N2%、体力が$N3%増加します。",
      out = "ナクスラーマスの中にいる間、あなたの潜在能力を解放します。装備しているサンクティファイドアイテム一つにつき、生み出す脅威が$N1%、与えるダメージが$N2%、体力が$N3%増加します。" },
    { id = "spell:1226843:description", html = false,
      ja = "Just a Flesh Woundが有効でない間、Backstab、Sinister Strike、Saber Slash、Mutilateのダメージが、対象にかかっている自分の有効なPoisonまたはBleedの効果一つにつき$N1%増加します。増加は最大$N2%までです。",
      out = "ジャスト・ア・フレッシュ・ウーンドが有効でない間、バックスタブ、シニスター・ストライク、セイバー・スラッシュ、ミューティレートのダメージが、対象にかかっている自分の有効なポイズンまたはブリードの効果一つにつき$N1%増加します。増加は最大$N2%までです。" },
    { id = "spell:1230980:description", html = false,
      ja = "Standard of Stiltzを投げ立て、$D1の間、近くにいるすべての味方の最大体力を$N1増加させます。",
      out = "スタンダード・オブ・スティルツを投げ立て、$D1の間、近くにいるすべての味方の最大体力を$N1増加させます。" },
    { id = "spell:1231906:description", html = false,
      ja = "BalnazzarがinfernalをScarlet Lightbearerの妨害に呼び出し、$N2ヤード以内に$N1のFireダメージを与え、命中したプレイヤーを$N3の間スタンさせます。",
      out = "バルナザールがインファーナルをスカーレット・ライトベアラーの妨害に呼び出し、$N2ヤード以内に$N1のファイアダメージを与え、命中したプレイヤーを$N3の間スタンさせます。" },
    { id = "spell:1235318:description", html = false,
      ja = "炎の波を放ち、近くの敵にFireダメージを与え、$D1の間、移動速度を低下させます。",
      out = "炎の波を放ち、近くの敵にファイアダメージを与え、$D1の間、移動速度を低下させます。" },
    { id = "spell:1241524:description", html = false,
      ja = "マナを込めたオーブをランダムなプレイヤーに向けて放ちます。オーブは飛んでいき、元の位置に戻ってきます。命中したプレイヤーは$N1のArcaneダメージを受けます。",
      out = "マナを込めたオーブをランダムなプレイヤーに向けて放ちます。オーブは飛んでいき、元の位置に戻ってきます。命中したプレイヤーは$N1のアーケインダメージを受けます。" },
    { id = "spell:1248687:description", html = false,
      ja = "$D1かけて体力を$N1回復します。食事中は座っている必要があります。10秒以上食事をすると満腹状態になり、$D3の間、Westfallにいる間、移動速度が$N4%上昇します。$?pc142418[さらに、敵を倒して得る経験値が$N6%増加します。][]",
      out = "$D1かけて体力を$N1回復します。食事中は座っている必要があります。10秒以上食事をすると満腹状態になり、$D3の間、ウェストフォールにいる間、移動速度が$N4%上昇します。$?pc142418[さらに、敵を倒して得る経験値が$N6%増加します。][]" },
    { id = "spell:1253332:description", html = false,
      ja = "敵に毒を放ち、$N1のNatureダメージを与え、その後$D2の間、$D1ごとに追加のダメージを与えます。",
      out = "敵に毒を放ち、$N1のネイチャーダメージを与え、その後$D2の間、$D1ごとに追加のダメージを与えます。" },
    { id = "spell:1263079:description", html = false,
      ja = "Sewing Machineを製作します。",
      out = "ソーイング・マシンを製作します。" },
    { id = "spell:1269404:description", html = false,
      ja = "敵に負のエネルギーの矢を放ち、$N1のShadowダメージを与え、$D1の間、Shrouding Boltから受けるダメージをスタックごとに$N2%増加させます。",
      out = "敵に負のエネルギーの矢を放ち、$N1のシャドウダメージを与え、$D1の間、シュラウディング・ボルトから受けるダメージをスタックごとに$N2%増加させます。" },
    { id = "spell:1272606:description", html = false,
      ja = "ランダムなターゲットの位置に空から矢の雨を降らせ、$D1ごとに$N1%のPhysicalダメージを与えます。",
      out = "ランダムなターゲットの位置に空から矢の雨を降らせ、$D1ごとに$N1%のフィジカルダメージを与えます。" },
    { id = "spell:1284560:description", html = false,
      ja = "Darkspear Flagを持っています。\r\nこの旗を支配下の拠点に運ぶとVictory Pointsを獲得できます。",
      out = "ダークスピア・フラッグを持っています。\r\nこの旗を支配下の拠点に運ぶとビクトリー・ポイントを獲得できます。" },
    { id = "spell:1289849:description", html = false,
      ja = "Main Handの近接自動攻撃で、Off Hand武器による即時の追加攻撃が発生することがあり、通常ダメージの$N1%を与えます。",
      out = "メイン・ハンドの近接自動攻撃で、オフ・ハンド武器による即時の追加攻撃が発生することがあり、通常ダメージの$N1%を与えます。" },
    { id = "spell:1293526:description", html = false,
      ja = "鷹に命じて狙った敵へ急降下攻撃させ、$N1のPhysicalダメージを与え、$D1の間攻撃を続けさせます。同時に有効にできる鷹は$N3羽までです。Summon HawkはArcane Shotとクールダウンを共有します。",
      out = "鷹に命じて狙った敵へ急降下攻撃させ、$N1のフィジカルダメージを与え、$D1の間攻撃を続けさせます。同時に有効にできる鷹は$N3羽までです。サモン・ホークはアーケイン・ショットとクールダウンを共有します。" },
    { id = "spell:1294888:description", html = false,
      ja = "Anara ChillwindがEluneの優雅さを導き、ランダムな敵に星の力を注ぎ込み、$D2の間、$D1ごとに$N1のArcaneダメージを与えます。効果が取り除かれると、崩壊する星が生まれます。星の中にいる敵は$D3ごとに$N4のArcaneダメージを受け、移動速度が$N6%低下します。",
      out = "アナラ・チルウィンドがエルーンの優雅さを導き、ランダムな敵に星の力を注ぎ込み、$D2の間、$D1ごとに$N1のアーケインダメージを与えます。効果が取り除かれると、崩壊する星が生まれます。星の中にいる敵は$D3ごとに$N4のアーケインダメージを受け、移動速度が$N6%低下します。" },
    { id = "spell:1300344:description", html = false,
      ja = "片手武器とOff Hand武器をOff Handに装備できるようになります。",
      out = "片手武器とオフ・ハンド武器をオフ・ハンドに装備できるようになります。" },
    { id = "spell:1302650:description", html = false,
      ja = "Right Clickで霊体の子グマを召喚、または解放します。",
      out = "ライト・クリックで霊体の子グマを召喚、または解放します。" },
    { id = "spell:1306699:aura", html = false,
      ja = "Mountainousの地域では、与える治療量が最大$N1、呪文ダメージが最大$N2増加します。",
      out = "マウンテナスの地域では、与える治療量が最大$N1、呪文ダメージが最大$N2増加します。" },
    { id = "spell:1309323:description", html = false,
      ja = "$N1のShadowflameダメージを与えます。",
      out = "$N1のシャドウフレイムダメージを与えます。" },
    { id = "spell:1311705:aura", html = false,
      ja = "Seal of Justiceが有効でない次の近接攻撃を、$N1回分のSeal of Justiceで強化します。",
      out = "シール・オブ・ジャスティスが有効でない次の近接攻撃を、$N1回分のシール・オブ・ジャスティスで強化します。" },
    { id = "spell:1318002:aura", html = false,
      ja = "ForestまたはGrasslandの地域では、魔法の呪文と効果によるダメージと治療量がさらに$N1増加します。",
      out = "フォレストまたはグラスランドの地域では、魔法の呪文と効果によるダメージと治療量がさらに$N1増加します。" },
    { id = "spell:1324288:description", html = false,
      ja = "Defenseが$N1増加します。",
      out = "ディフェンスが$N1増加します。" },
    { id = "spell:13298:aura", html = false,
      ja = "$D1ごとにNatureダメージを受けています。",
      out = "$D1ごとにネイチャーダメージを受けています。" },
    { id = "spell:13797:aura", html = false,
      ja = "$N2秒ごとに$N1のFireダメージを受けます。",
      out = "$N2秒ごとに$N1のファイアダメージを受けます。" },
    { id = "spell:14301:description", html = false,
      ja = "$N2秒ごとに$N1のFireダメージを与えます。",
      out = "$N2秒ごとに$N1のファイアダメージを与えます。" },
    { id = "spell:14634:description", html = false,
      ja = "Nature Resistanceが$N1上昇します。",
      out = "ネイチャー・レジスタンスが$N1上昇します。" },
    { id = "spell:14929:description", html = false,
      ja = "Un'GoroのGolakka craterで満たします。",
      out = "ウンゴロのゴラッカ・クレーターで満たします。" },
    { id = "spell:15473:aura", html = false,
      ja = "与えるShadowダメージが$N1%増加します。すべてのShadow呪文のマナコストが$N2%減少します。Shadow呪文のクリティカルダメージボーナスが$N3%増加します。受ける物理ダメージが$N4%減少します。治療呪文を詠唱できません。",
      out = "与えるシャドウダメージが$N1%増加します。すべてのシャドウ呪文のマナコストが$N2%減少します。シャドウ呪文のクリティカルダメージボーナスが$N3%増加します。受ける物理ダメージが$N4%減少します。治療呪文を詠唱できません。" },
    { id = "spell:15814:description", html = false,
      ja = "Attack Powerが$N1上昇します。",
      out = "アタック・パワーが$N1上昇します。" },
    { id = "spell:16098:description", html = false,
      ja = "$D1の間、周囲の敵が受けるPhysicalダメージを$N1増加させます。",
      out = "$D1の間、周囲の敵が受けるフィジカルダメージを$N1増加させます。" },
    { id = "spell:16757:description", html = false,
      ja = "Frostbolt、Ice Lance、Blizzardの射程と、Frost NovaとCone of Coldの効果範囲を$N1%増加させます。",
      out = "フロストボルト、アイス・ランス、ブリザードの射程と、フロスト・ノヴァとコーン・オブ・コールドの効果範囲を$N1%増加させます。" },
    { id = "spell:17183:description", html = false,
      ja = "対象を毒に冒し、$D2の間、$D1ごとに$N1のNatureダメージを与えます。",
      out = "対象を毒に冒し、$D2の間、$D1ごとに$N1のネイチャーダメージを与えます。" },
    { id = "spell:17651:description", html = false,
      ja = "Spectral Projectionを$N1体召喚し、術者の代わりに戦わせます。術者は透明かつ無敵になりますが、行動できません。$D1後、幻影たちは自らの命を犠牲にして術者を回復し、術者は戦いに戻ります。",
      out = "スペクトラル・プロジェクションを$N1体召喚し、術者の代わりに戦わせます。術者は透明かつ無敵になりますが、行動できません。$D1後、幻影たちは自らの命を犠牲にして術者を回復し、術者は戦いに戻ります。" },
    { id = "spell:17934:description", html = false,
      ja = "Fireダメージの発動効果。",
      out = "ファイアダメージの発動効果。" },
    { id = "spell:18214:description", html = false,
      ja = "敵に影の矢を放ち、$N1のShadowダメージを与えます。",
      out = "敵に影の矢を放ち、$N1のシャドウダメージを与えます。" },
    { id = "spell:18832:description", html = false,
      ja = "体力を$N1、マナを$N2回復します。使用するにはLei of Lilliesを装備している必要があります。",
      out = "体力を$N1、マナを$N2回復します。使用するにはレイ・オブ・ユリを装備している必要があります。" },
    { id = "spell:19480:description", html = false,
      ja = "Felhunterの$N1ヤード以内にいるすべてのパーティメンバーのステルス探知を、レベルが$N2高いかのように上昇させます。",
      out = "フェルハンターの$N1ヤード以内にいるすべてのパーティメンバーのステルス探知を、レベルが$N2高いかのように上昇させます。" },
    { id = "spell:19890:description", html = false,
      ja = "Artisan Fishermanになる方法を習得し、釣りスキルの上限が$N1になります。",
      out = "アルチザン・フィッシャーマンになる方法を習得し、釣りスキルの上限が$N1になります。" },
    { id = "spell:20302:aura", html = false,
      ja = "受けるHolyダメージが最大$N1増加します。",
      out = "受けるホーリーダメージが最大$N1増加します。" },
    { id = "spell:20607:description", html = false,
      ja = "Stavesのスキルが$N1上昇します。",
      out = "ステイヴのスキルが$N1上昇します。" },
    { id = "spell:20930:description", html = false,
      ja = "対象にHolyエネルギーを放ち、敵には$N1のHolyダメージを、味方には$N2の回復を与えます。",
      out = "対象にホーリーエネルギーを放ち、敵には$N1のホーリーダメージを、味方には$N2の回復を与えます。" },
    { id = "spell:21452:description", html = false,
      ja = "遠隔のAttack Powerが$N1上昇します。",
      out = "遠隔のアタック・パワーが$N1上昇します。" },
    { id = "spell:21992:description", html = false,
      ja = "稲妻で敵を撃ち、$N1のNatureダメージを与え、周囲の敵へと次々に飛び移ります。飛び移るたびに、その対象のNature耐性を$N2低下させます。$N3体の対象に効果があります。主目標はさらに竜巻に巻き込まれ、$D1の間攻撃速度が$N4%低下します。",
      out = "稲妻で敵を撃ち、$N1のネイチャーダメージを与え、周囲の敵へと次々に飛び移ります。飛び移るたびに、その対象のネイチャー耐性を$N2低下させます。$N3体の対象に効果があります。主目標はさらに竜巻に巻き込まれ、$D1の間攻撃速度が$N4%低下します。" },
    { id = "spell:22920:description", html = false,
      ja = "Arcaneの魔法で敵を撃ち、通常のダメージに加えて$N1のダメージを与え、吹き飛ばします。",
      out = "アーケインの魔法で敵を撃ち、通常のダメージに加えて$N1のダメージを与え、吹き飛ばします。" },
    { id = "spell:23337:description", html = false,
      ja = "敵を撃ち、Physicalダメージを与えます。",
      out = "敵を撃ち、フィジカルダメージを与えます。" },
    { id = "spell:24109:description", html = false,
      ja = "$D1の間、味方が与えるPhysicalダメージを$N1増加させます。",
      out = "$D1の間、味方が与えるフィジカルダメージを$N1増加させます。" },
    { id = "spell:24482:description", html = false,
      ja = "SmiteとHoly Fireの射程を$N1ヤード延ばします。",
      out = "スマイトとホーリー・ファイアの射程を$N1ヤード延ばします。" },
    { id = "spell:24833:description", html = false,
      ja = "Holy Mightstoneを砕き、Undeadに対するAttack Powerを$N1上昇させ、Undeadに対する呪文と効果によるHolyダメージを最大$N2増加させます。効果時間は$D1です。",
      out = "ホーリー・マイトストーンを砕き、アンデッドに対するアタック・パワーを$N1上昇させ、アンデッドに対する呪文と効果によるホーリーダメージを最大$N2増加させます。効果時間は$D1です。" },
    { id = "spell:25346:description", html = false,
      ja = "敵にArcane Missileを放ち、$N1のArcaneダメージを与えます。",
      out = "敵にアーケイン・ミサイルを放ち、$N1のアーケインダメージを与えます。" },
    { id = "spell:26143:description", html = false,
      ja = "敵にShadowダメージを与え、$D1の間、移動速度を低下させます。",
      out = "敵にシャドウダメージを与え、$D1の間、移動速度を低下させます。" },
    { id = "spell:26705:description", html = false,
      ja = "Arcaneの呪文と効果によるダメージを最大$N1増加させます。",
      out = "アーケインの呪文と効果によるダメージを最大$N1増加させます。" },
    { id = "spell:27743:description", html = false,
      ja = "Gunsが+$N1上昇します。",
      out = "ガンが+$N1上昇します。" },
    { id = "spell:2860:description", html = false,
      ja = "敵に稲妻を放ってNatureダメージを$N1与え、その後近くにいる別の敵へ跳躍します。跳躍するたびにダメージが$N2%減少します。合計$N3体の対象に効果があります。",
      out = "敵に稲妻を放ってネイチャーダメージを$N1与え、その後近くにいる別の敵へ跳躍します。跳躍するたびにダメージが$N2%減少します。合計$N3体の対象に効果があります。" },
    { id = "spell:29419:description", html = false,
      ja = "半径5ヤード以内のすべてのBeastsを$D1の間逃げ出させます。",
      out = "半径5ヤード以内のすべてのビーストを$D1の間逃げ出させます。" },
    { id = "spell:324:description", html = false,
      ja = "術者の周囲に$N1個の雷球が現れます。呪文、近接攻撃、遠隔攻撃が術者に命中すると、攻撃者は$N2のNatureダメージを受けます。これで雷球を1個消費します。雷球が放たれるのは数秒に1個だけです。効果時間は$D1です。",
      out = "術者の周囲に$N1個の雷球が現れます。呪文、近接攻撃、遠隔攻撃が術者に命中すると、攻撃者は$N2のネイチャーダメージを受けます。これで雷球を1個消費します。雷球が放たれるのは数秒に1個だけです。効果時間は$D1です。" },
    { id = "spell:36936:description", html = false,
      ja = "トーテムを大地に還し、Totemic Recallで破壊した各トーテムの詠唱に必要なマナの$N1%を得ます。",
      out = "トーテムを大地に還し、トーテミック・リコールで破壊した各トーテムの詠唱に必要なマナの$N1%を得ます。" },
    { id = "spell:401699:description", html = false,
      ja = "Azora Apprentice Notesを8枚組み合わせて、新しいルーン彫刻のレシピを見つけます。",
      out = "アゾラ・アプレンティス・ノートを8枚組み合わせて、新しいルーン彫刻のレシピを見つけます。" },
    { id = "spell:403873:description", html = false,
      ja = "Metamorphosisのアビリティを得ます：\n\n$I1\nDemonに変身し、アーマーを$N1%、体力を$N2%増加させ、クリティカルヒットを受ける確率を$N3%減少させ、脅威を$N4%増加させ、Life Tapで得るマナを$N5%増加させますが、与えるすべてのダメージが$N6%減少します。Metamorphosisは一部のアビリティの機能を変化させ、新しいアビリティを与えます：\n\nSearing Pain：即時になります。\n\nShadow Bolt：Shadow Cleaveになります。近くの敵最大$N7体に命中するShadowの近接攻撃ですが、$D1のクールダウンがあります。\n\nFear：Menaceに置き換わります。\n\n$I2\n対象をTauntして自分を攻撃させますが、対象がすでに自分を攻撃している場合は効果がありません。\n\nDemon Charge\n\n$I3\n敵に突進し、$D2の間スタンさせます。戦闘中は使用できません。\n\nDemonic Howl\n\n$I4\n$D3の間、近くのすべての敵に自分を集中攻撃させます。",
      out = "メタモルフォシスのアビリティを得ます：\n\n$I1\nデーモンに変身し、アーマーを$N1%、体力を$N2%増加させ、クリティカルヒットを受ける確率を$N3%減少させ、脅威を$N4%増加させ、ライフ・タップで得るマナを$N5%増加させますが、与えるすべてのダメージが$N6%減少します。メタモルフォシスは一部のアビリティの機能を変化させ、新しいアビリティを与えます：\n\nシアリング・ペイン：即時になります。\n\nシャドウ・ボルト：シャドウ・クリーヴになります。近くの敵最大$N7体に命中するシャドウの近接攻撃ですが、$D1のクールダウンがあります。\n\nフィアー：メナスに置き換わります。\n\n$I2\n対象をトーントして自分を攻撃させますが、対象がすでに自分を攻撃している場合は効果がありません。\n\nデーモン・チャージ\n\n$I3\n敵に突進し、$D2の間スタンさせます。戦闘中は使用できません。\n\nデモニック・ハウル\n\n$I4\n$D3の間、近くのすべての敵に自分を集中攻撃させます。" },
    { id = "spell:409583:aura", html = false,
      ja = "能力値が$N1%、Attack Powerが$N2増加します。",
      out = "能力値が$N1%、アタック・パワーが$N2増加します。" },
    { id = "spell:412718:description", html = false,
      ja = "Raw Brilliant Smallfishの切り身を作ってみます。",
      out = "ロー・ブリリアント・スモールフィッシュの切り身を作ってみます。" },
    { id = "spell:416008:description", html = false,
      ja = "脚部にEverlasting Afflictionのルーンを刻みます：\r\n\n$I1\r\nDrain Life、Drain Soul、Shadowboltがダメージを与えるたびに、対象にかかっているCorruptionの効果時間が最大まで更新されます。",
      out = "脚部にエバーラスティング・アフリクションのルーンを刻みます：\r\n\n$I1\r\nドレイン・ライフ、ドレイン・ソウル、シャドウボルトがダメージを与えるたびに、対象にかかっているコラプションの効果時間が最大まで更新されます。" },
    { id = "spell:425211:description", html = false,
      ja = "Void Plagueのアビリティを得ます：\n\n$I1\n対象を病気に冒し、$D1かけて$N1のShadowダメージを与えます。",
      out = "ヴォイド・プレイグのアビリティを得ます：\n\n$I1\n対象を病気に冒し、$D1かけて$N1のシャドウダメージを与えます。" },
    { id = "spell:427066:aura", html = false,
      ja = "激怒しています。Mortal Strike、Bloodthirst、Shield Slamのダメージが$N1%増加します。",
      out = "激怒しています。モータル・ストライク、ブラッドサースト、シールド・スラムのダメージが$N1%増加します。" },
    { id = "spell:430377:description", html = false,
      ja = "Light Hideを$N1枚加えて、出荷品を完成させます。",
      out = "ライト・ハイドを$N1枚加えて、出荷品を完成させます。" },
    { id = "spell:433546:aura", html = false,
      ja = "$D1ごとに$N1のNatureダメージを受けています。",
      out = "$D1ごとに$N1のネイチャーダメージを受けています。" },
    { id = "spell:436347:description", html = false,
      ja = "血と光の爆発を遅れて放ち、$N2ヤード以内のすべての対象に$N1のTwilightダメージを与えます。",
      out = "血と光の爆発を遅れて放ち、$N2ヤード以内のすべての対象に$N1のトワイライトダメージを与えます。" },
    { id = "spell:437868:aura", html = false,
      ja = "$D1ごとに$N1のShadowダメージを受けます。\r\n与えるダメージが$N3%減少します。",
      out = "$D1ごとに$N1のシャドウダメージを受けます。\r\n与えるダメージが$N3%減少します。" },
    { id = "spell:440790:description", html = false,
      ja = "外套にShock and Aweのルーンを刻みます：\n\n$I1\nRighteous Furyが有効でない間、Holy Shockでダメージを与えると、知力の$N1%をSpell Damageとして得て、$D1の間、生み出す脅威が$N2%減少します。\n\nInfusion of Lightが刻まれている場合、$D2の間Sunlightを得ます。\n\n$I2\nSunlightにより、Divine Storm、Crusader Strike、およびプレイヤー以外が操作する対象への近接攻撃が、神聖呪文パワーの$N5%に等しい追加のHolyダメージを与えます。",
      out = "外套にショック・アンド・オーのルーンを刻みます：\n\n$I1\nライチャス・フューリーが有効でない間、ホーリー・ショックでダメージを与えると、知力の$N1%をスペル・ダメージとして得て、$D1の間、生み出す脅威が$N2%減少します。\n\nインフュージョン・オブ・ライトが刻まれている場合、$D2の間サンライトを得ます。\n\n$I2\nサンライトにより、ディバイン・ストーム、クルセイダー・ストライク、およびプレイヤー以外が操作する対象への近接攻撃が、神聖呪文パワーの$N5%に等しい追加のホーリーダメージを与えます。" },
    { id = "spell:446134:description", html = false,
      ja = "Heavy Mageweave Bandageを$N1個追加して、出荷を完了させます。",
      out = "ヘヴィー・メイジウィーブ・バンデージを$N1個追加して、出荷を完了させます。" },
    { id = "spell:4480:description", html = false,
      ja = "Two-Handed Macesでのダメージが$N1増加します。",
      out = "ツー・ハンデッド・メイスでのダメージが$N1増加します。" },
    { id = "spell:4561:description", html = false,
      ja = "Nature耐性が$N1増加し、$N2%の確率で敵対するNature呪文を術者に反射します。",
      out = "ネイチャー耐性が$N1増加し、$N2%の確率で敵対するネイチャー呪文を術者に反射します。" },
    { id = "spell:459714:description", html = false,
      ja = "Touch of Weaknessのアビリティを得ます：\n\n$I1\n術者への次の近接攻撃は攻撃者に$N1のShadowダメージを与え、$D1の間、攻撃者の近接攻撃力を$N2低下させます。",
      out = "タッチ・オブ・ウィークネスのアビリティを得ます：\n\n$I1\n術者への次の近接攻撃は攻撃者に$N1のシャドウダメージを与え、$D1の間、攻撃者の近接攻撃力を$N2低下させます。" },
    { id = "spell:461689:description", html = false,
      ja = "ShadowstrikeをThunderstrikeに変えます。",
      out = "シャドウストライクをサンダーストライクに変えます。" },
    { id = "spell:465418:description", html = false,
      ja = "戦闘の構えを変え、Truthbearerを両手剣として扱います。",
      out = "戦闘の構えを変え、トゥルースベアラーを両手剣として扱います。" },
    { id = "spell:467740:description", html = false,
      ja = "敵に影の矢を放ち、$N1のShadowダメージを与えます。",
      out = "敵に影の矢を放ち、$N1のシャドウダメージを与えます。" },
    { id = "spell:468836:description", html = false,
      ja = "ソウルシャードをDepleted Scythe of Chaosと組み合わせます。",
      out = "ソウルシャードをディプリーテッド・サイズ・オブ・カオスと組み合わせます。" },
    { id = "spell:472:description", html = false,
      ja = "Pintoを召喚/退散します。",
      out = "ピントを召喚/退散します。" },
    { id = "spell:4920:description", html = false,
      ja = "すべてのBowsでのクリティカル率が1%増加します。",
      out = "すべてのボウでのクリティカル率が1%増加します。" },
    { id = "spell:5448:description", html = false,
      ja = "One-Handed Swordsでのダメージが$N1増加します。",
      out = "ワン・ハンデッド・ソードでのダメージが$N1増加します。" },
    { id = "spell:5844:description", html = false,
      ja = "Fire呪文のダメージが$N1増加します。",
      out = "ファイア呪文のダメージが$N1増加します。" },
    { id = "spell:6366:description", html = false,
      ja = "Lesser Firestoneを作成します。これを使うと武器にFireを付与し、呪文のクリティカル率を$N1%、Fire呪文のダメージを最大$N2上げます。\n\nログアウトしてから15分以上経つと、創造されたアイテムは消えます。",
      out = "レッサー・ファイアストーンを作成します。これを使うと武器にファイアを付与し、呪文のクリティカル率を$N1%、ファイア呪文のダメージを最大$N2上げます。\n\nログアウトしてから15分以上経つと、創造されたアイテムは消えます。" },
    { id = "spell:7139:description", html = false,
      ja = "周囲の敵に通常ダメージに加えて$N1を与え、$D1の間スタンさせ、受けるPhysicalダメージを$N3増加させます。",
      out = "周囲の敵に通常ダメージに加えて$N1を与え、$D1の間スタンさせ、受けるフィジカルダメージを$N3増加させます。" },
    { id = "spell:7655:description", html = false,
      ja = "敵に呪いをかけ、$D1の間、与えるPhysicalダメージを$N1、魔法ダメージを$N2減少させます。また、この呪いにより$D2の間、術者が与えるPhysicalダメージが$N4、魔法ダメージが$N5増加します。",
      out = "敵に呪いをかけ、$D1の間、与えるフィジカルダメージを$N1、魔法ダメージを$N2減少させます。また、この呪いにより$D2の間、術者が与えるフィジカルダメージが$N4、魔法ダメージが$N5増加します。" },
    { id = "spell:8103:description", html = false,
      ja = "対象に$N1のShadowダメージを与えますが、大量の脅威を発生させます。",
      out = "対象に$N1のシャドウダメージを与えますが、大量の脅威を発生させます。" },
    { id = "spell:8516:description", html = false,
      ja = "Attack Powerが$N1増加します。Extra Attackを$N2回得ます。",
      out = "アタック・パワーが$N1増加します。エクストラ・アタックを$N2回得ます。" },
    { id = "spell:9307:description", html = false,
      ja = "Frost呪文と効果によるダメージが最大$N1増加します。",
      out = "フロスト呪文と効果によるダメージが最大$N1増加します。" },
  },
}
